var EX_DESC={sentadilla_trasera:{b:"shown from the side at the bottom of a back squat, a loaded olympic barbell resting across the upper back and rear shoulders, hips sunk to just below the knee crease, shins near vertical, knees tracking over the toes, chest tall and spine long",c:"Barra sobre el trapecio, baja hasta romper la paralela con el pecho alto y las rodillas siguiendo la punta del pie."},sentadilla_frontal:{b:"shown from the side at the bottom of a front squat, an olympic barbell racked across the FRONT of the shoulders with high elbows pointing forward, upright torso, hips below the knees, weight over the mid-foot",c:"Barra en la clav\xEDcula con codos altos al frente; mant\xE9n el torso muy vertical y baja profundo."},sentadilla_goblet:{b:"shown from the front at the bottom of a goblet squat, holding one dumbbell vertically against the chest cupped with both hands, elbows inside the knees, hips deep, chest proud and heels down",c:"Sujeta la mancuerna vertical contra el pecho; baja entre las rodillas manteniendo los talones en el suelo."},bulgara:{b:"shown from the side at the bottom of a Bulgarian split squat, the REAR foot elevated behind on a bench, front shin vertical with the knee over the ankle, rear knee sinking toward the floor, torso slightly forward, a dumbbell in each hand",c:"Pie de atr\xE1s sobre el banco; baja recto hundiendo la cadera hasta que el muslo delantero quede paralelo."},sf_sentadilla:{b:"shown from the side at the bottom of a barbell squat, bar on the upper back, hips just below the knees, shins near vertical, flat neutral spine, weight balanced over the mid-foot",c:"Baja controlado hasta la paralela, rodillas alineadas con los pies y core apretado; empuja con todo el pie."},sf_sentadilla_hack:{b:"shown from the side on a 45\xB0 hack-squat machine, back and shoulders pressed against the angled sliding pad, feet high on the platform, knees bending deeply toward the chest, driving the sled through the heels",c:"Espalda pegada al respaldo de la m\xE1quina; baja profundo con las rodillas siguiendo los pies y empuja con el tal\xF3n."},sf_extension_a_una_pierna:{b:"shown from the side seated tall on a bench, one leg extending straight out from the knee to horizontal, toes up, the other foot flat on the floor, quadriceps of the working leg fully contracted",c:"Sentado, estira una rodilla hasta dejar la pierna recta apretando el cu\xE1driceps; baja despacio."},sf_sentadilla_goblet_con_mancuerna:{b:"shown from the front at the bottom of a goblet squat holding a single dumbbell vertically at the chest with both hands, elbows tracking inside the knees, deep hips, upright chest, heels planted",c:"Mancuerna vertical al pecho, codos por dentro de las rodillas; baja profundo con el tronco erguido."},sf_sentadillas_con_propio_peso:{b:"shown from the side at the bottom of a bodyweight air squat, arms reaching forward as a counterbalance, hips below the knees, chest up, heels down, neutral spine",c:"Sin peso: baja hasta la paralela con los brazos al frente de contrapeso y el pecho alto."},sf_uno_y_medio_repeticiones_de_sentadillas_con_propio_peso:{b:"shown from the side mid bodyweight squat rising only halfway, captured at the half-way turnaround of a one-and-a-half-rep squat, arms forward, thighs still below parallel, clear sense of a partial ascent",c:"Baja del todo, sube solo hasta la mitad, vuelve a bajar y entonces sube completo: eso es una repetici\xF3n."},sf_sentadillas_con_balon_medicinal:{b:"shown from the front at the bottom of a squat holding a medicine ball at chest height with both hands, elbows in, hips deep between the heels, torso upright",c:"Bal\xF3n medicinal a la altura del pecho; baja entre los talones sin dejar caer el tronco."},sf_sentadilla_bulgara_con_barra:{b:"shown from the side at the bottom of a Bulgarian split squat with an olympic barbell across the upper back, rear foot elevated on a bench, front shin vertical, rear knee low, torso tall",c:"Barra en la espalda y pie trasero elevado; baja vertical cargando el gl\xFAteo de la pierna delantera."},sf_sentadilla_bulgara_con_propio_peso:{b:"shown from the side at the bottom of a bodyweight Bulgarian split squat, rear foot on a bench behind, front shin vertical, hands at the chest for balance, rear knee sinking low",c:"Pie de atr\xE1s en el banco, manos al pecho; baja recto hasta rozar el suelo con la rodilla trasera."},sf_sentadilla_con_mini_banda:{b:"shown from the front at the bottom of a bodyweight squat with a mini resistance band looped just above the knees, actively pushing the knees OUT against the band, hips deep, chest up",c:"Banda por encima de las rodillas; emp\xFAjalas hacia fuera contra la goma durante toda la bajada y subida."},sf_sentadilla_isometrica_apoyado_sobre_la_pared:{b:"shown from the side holding an isometric wall sit, back flat against a wall, thighs horizontal and shins vertical so hips and knees make right angles, arms relaxed, static hold",c:"Espalda en la pared y muslos paralelos al suelo (90\xB0); aguanta la posici\xF3n sin bajar la cadera."},sf_sentadilla_sumo_con_kettlebell:{b:"shown from the front at the bottom of a wide sumo squat, feet wide with toes turned out, a kettlebell hanging between the legs held with both hands, hips dropping straight down, torso upright",c:"Piernas anchas con puntas hacia fuera y kettlebell colgando entre ellas; baja la cadera recta hacia el suelo."},sf_los_groiners:{b:"shown from the side in a groiner, a dynamic mobility drill: starting from a high plank, one foot has stepped up flat to the OUTSIDE of the same-side hand into a deep low lunge, back leg straight, hips sinking low, chest open",c:"Desde plancha alta, lleva un pie plano por fuera de la mano hasta un zancada profunda; alterna con control."},sf_hidrantes:{b:"shown from the side on all fours (fire hydrant), hands under shoulders and knees under hips, lifting one bent knee out to the SIDE to hip height like a dog at a hydrant, hips level, glute working",c:"A cuatro apoyos, abre una rodilla flexionada hacia el lateral sin girar la cadera; nota el gl\xFAteo medio."},sf_elevaciones_de_cadera_con_maquina_smith:{b:"shown from the side at the top of a hip thrust in a Smith machine, upper back braced across a bench, the guided bar over the hips, hips fully extended to a flat table-top, shins vertical, glutes squeezed",c:"Espalda apoyada en el banco y barra guiada sobre la cadera; sube hasta alinear tronco y muslos apretando el gl\xFAteo."},sf_elevaciones_de_cadera_con_barra:{b:"shown from the side at the top of a barbell hip thrust, shoulder blades resting on a bench, a padded olympic barbell across the hips, hips driven up to full extension level with the knees, shins vertical, ribs down",c:"Om\xF3platos en el banco y barra sobre la cadera; empuja hasta que tronco y muslos formen una l\xEDnea recta."},sf_elevaciones_en_posicion_de_rana_con_propio_peso:{b:"shown from the side at the top of a frog pump, lying on the back with the soles of the feet pressed together and knees splayed wide open, driving the hips up toward the ceiling, glutes squeezed",c:"Tumbado, junta las plantas y abre las rodillas; sube la cadera apretando el gl\xFAteo en un rango corto."},sf_elevaciones_cortas_en_posicion_de_rana_con_maquina_smith:{b:"shown from the side doing short-range frog pumps under a Smith-machine bar, lying supine with soles together and knees open, the guided bar resting on the hips, small pulsing hip lifts, glutes engaged",c:"Plantas juntas y rodillas abiertas bajo la barra guiada; sube la cadera en recorrido corto y apretado."},sf_almejas_laterales_con_banda:{b:"shown from the side lying on one side (clamshell), hips and knees bent and stacked, a mini band around the thighs, rotating the top knee open like a clam while the feet stay together, glute medius working",c:"De lado con rodillas flexionadas y banda en los muslos; abre la rodilla de arriba sin mover la pelvis."},sf_levantamiento_de_pierna_acostado_de_lado:{b:"shown from the side lying on one side with the body in a straight line, the bottom arm supporting the head, raising the top straight leg up to about 45\xB0 with the toe forward, outer hip working",c:"Tumbado de lado y cuerpo recto; sube la pierna de arriba estirada sin balancear la cadera."},sf_columpios_con_kettlebell:{b:"shown from the side at the top of a kettlebell swing, a kettlebell swung up to about chest height by an explosive hip snap, arms straight and relaxed, hips and knees just extended, flat back \u2014 a hip hinge, not a squat",c:"El impulso sale de la cadera, no de los brazos: proyecta la kettlebell con un golpe de gl\xFAteo hasta el pecho."},sf_elevaciones_de_cadera_acostado_lateralmente:{b:"shown from the front lying on one side propped on the forearm (side-lying hip raise), body straight, lifting the hips off the floor so the torso and legs form one rigid diagonal line, obliques and glute medius bracing",c:"Ap\xF3yate en el antebrazo de lado y sube la cadera hasta formar una l\xEDnea recta de cabeza a pies."},sf_sentadilla_posturas_funcionales:{b:"shown from the front holding the bottom of a deep bodyweight squat as a mobility posture, heels flat, hips below the knees, elbows gently pressing the knees open, tall relaxed spine, calm controlled hold",c:"Baja a una sentadilla profunda con talones en el suelo y \xE1brete las rodillas con los codos; respira y mant\xE9n."},peso_muerto_convencional:{b:"shown from the side at the start of a conventional deadlift, an olympic barbell on the floor at mid-shin, hips higher than the knees, long flat back, shoulders just in front of the bar, arms vertical, about to drive the floor away",c:"Barra pegada a la espinilla, espalda recta y pecho alto; empuja el suelo con las piernas y sube la barra rozando el cuerpo."},peso_muerto_rumano:{b:"shown from the side mid-Romanian-deadlift, standing with a barbell held at the thighs, hips pushed far back, soft unlocked knees, long flat back, bar sliding down along the legs to just below the knees, hamstrings loaded",c:"Desde arriba, lleva la cadera atr\xE1s bajando la barra pegada a la pierna con la espalda recta; nota el estiramiento del femoral."},hip_thrust:{b:"shown from the side at the top of a barbell hip thrust, upper back on a bench, a padded barbell across the hips, hips fully extended to a flat table-top level with the knees, shins vertical, chin tucked, glutes locked",c:"Om\xF3platos en el banco, barra en la cadera; sube hasta alinear tronco y muslos y aprieta el gl\xFAteo arriba."},sf_peso_muerto_con_barra:{b:"shown from the side at the lift-off of a barbell deadlift, bar at mid-shin over the mid-foot, hips set between knees and shoulders, flat neutral spine, lats tight, arms straight",c:"Barra sobre el medio del pie, espalda neutra y brazos rectos; sube empujando con las piernas y bloquea la cadera arriba."},sf_peso_muerto_sumo_con_barra:{b:"shown from the front at the start of a sumo deadlift, a very wide stance with toes turned out, hands gripping the bar INSIDE the knees, torso more upright than a conventional pull, hips low, back flat",c:"Piernas muy abiertas y manos por dentro de las rodillas; tronco m\xE1s vertical, abre las rodillas y sube la barra."},sf_peso_muerto_con_barra_hexagonal:{b:"shown from the front standing INSIDE a hexagonal trap bar, gripping the two neutral side handles, hips set back, flat back, torso fairly upright, lifting the framed bar straight up beside the body",c:"Col\xF3cate dentro de la barra hexagonal y agarra las asas neutras; sube con el tronco algo m\xE1s vertical que el peso muerto normal."},sf_peso_muerto_con_mancuernas:{b:"shown from the side at the bottom of a dumbbell deadlift, a dumbbell in each hand hanging at the sides of the shins, hips back, flat back, knees soft, chest up, about to stand tall",c:"Mancuernas a los lados de las piernas; baja con la cadera atr\xE1s y espalda recta, y sube estirando cadera y rodillas juntas."},sf_peso_muerto_rumano_piernas_rectas_con_mancuernas:{b:"shown from the side in a stiff-legged Romanian deadlift with dumbbells, nearly straight knees, hips hinged far back, torso close to parallel with a flat back, dumbbells hanging just below the knees, hamstrings fully stretched",c:"Piernas casi rectas y cadera muy atr\xE1s; baja las mancuernas pegadas a la pierna sintiendo el femoral, espalda plana."},sf_peso_muerto_rumano_piernas_rectas_con_barra:{b:"shown from the side in a stiff-legged Romanian deadlift with a barbell, knees almost straight, deep hip hinge, torso near parallel with a long flat back, bar tracing the legs to mid-shin, hamstrings lengthened",c:"Rodillas casi bloqueadas, bisagra de cadera profunda; baja la barra rozando la pierna con la espalda recta."},sf_peso_muerto_con_balon_medicinal:{b:"shown from the side hinging to lift a medicine ball from the floor, hips back, flat back, knees soft, both hands cupping the ball between the shins, chest up, about to stand tall",c:"Bisagra de cadera para recoger el bal\xF3n del suelo con la espalda recta; sube estirando la cadera."},sf_peso_muerto_a_una_pierna:{b:"shown from the side in a single-leg Romanian deadlift, balanced on one slightly bent leg while the other leg extends straight back in line with the flat torso to form a horizontal 'T', a weight lowering toward the floor",c:"Sobre una pierna, lleva la otra recta atr\xE1s mientras bajas el peso; tronco y pierna forman una l\xEDnea, espalda plana."},sf_ejercicio_buenos_dias_con_barra:{b:"shown from the side performing a barbell good-morning, bar resting across the upper back like a squat, knees soft, hips pushed back to lower the flat torso toward horizontal, hamstrings and lower back loaded",c:"Barra en la espalda como en sentadilla; con las rodillas algo flexionadas, inclina el tronco al frente llevando la cadera atr\xE1s."},sf_puente_con_propio_peso:{b:"shown from the side at the top of a glute bridge, lying on the back with knees bent and feet flat, hips lifted so shoulders-hips-knees form a straight line, glutes squeezed at the top, arms resting on the floor",c:"Tumbado con los pies apoyados; sube la cadera hasta alinear rodillas, cadera y hombros apretando el gl\xFAteo."},sf_puentes_a_una_pierna:{b:"shown from the side at the top of a single-leg glute bridge, one foot flat on the floor driving the hips up, the other leg extended straight out level with the thigh, hips square and level, glute of the planted leg working",c:"Un pie apoyado y la otra pierna estirada; sube la cadera con un solo apoyo sin dejar que caiga un lado."},sf_puente_con_bandas:{b:"shown from the side at the top of a glute bridge with a mini band above the knees, feet flat, hips lifted to a straight line, knees pressed OUT against the band, glutes squeezed",c:"Banda sobre las rodillas; sube la cadera empujando las rodillas hacia fuera contra la goma."},zancadas:{b:"shown from the side at the bottom of a forward lunge, front shin vertical with the knee stacked over the ankle, rear knee lowered to just above the floor, torso upright and tall, a dumbbell optional in each hand",c:"Da un paso largo y baja recto hasta que la rodilla trasera casi toque el suelo; rodilla delantera sobre el tobillo."},step_up:{b:"shown from the side mid step-up, one foot planted flat on a knee-high box driving the body up onto it, torso slightly forward, the trailing leg extending, weight through the heel of the top foot",c:"Sube al caj\xF3n empujando con el tal\xF3n de la pierna de arriba, sin impulsarte con la de abajo."},sf_zancada:{b:"shown from the side at the bottom of a bodyweight lunge, front shin vertical, knee over the ankle, rear knee just above the floor, upright tall torso, hands at the hips for balance",c:"Zancada al frente bajando vertical; mant\xE9n el tronco erguido y la rodilla delantera sobre el pie."},sf_step_up_con_mancuernas:{b:"shown from the side mid step-up onto a box holding a dumbbell in each hand at the sides, one foot planted on top driving up through the heel, torso tall, trailing leg extending",c:"Con mancuernas a los lados, sube al caj\xF3n empujando con el tal\xF3n de arriba y mant\xE9n el tronco alto."},gemelos_pie:{b:"shown from the side at the top of a standing calf raise, standing tall with the balls of the feet on the edge of a step, heels lifted as high as possible into full plantarflexion, calves fully contracted",c:"De pie sobre el borde de un escal\xF3n, sube todo lo posible sobre las puntas y baja el tal\xF3n por debajo para estirar."},sf_elevacion_de_gemelos_sentado:{b:"shown from the side at the top of a seated calf raise, seated with knees bent at 90\xB0 and the balls of the feet on the floor or a small block, heels driven up as high as possible, soleus contracted",c:"Sentado con las rodillas a 90\xB0, sube los talones al m\xE1ximo sobre las puntas y controla la bajada."},gim_gemelo_prensa:{b:"shown from the side pressing through the toes on the platform of a 45\xB0 leg-press machine, legs almost straight, only the ankles moving to push the sled with the balls of the feet, calves contracted",c:"En la prensa con las piernas casi estiradas, empuja la plataforma solo con las puntas estirando el gemelo."},sf_extension_de_piernas:{b:"shown from the side seated with the shin behind a padded roller, extending both knees to lift the pad until the legs are straight and horizontal, toes up, quadriceps fully contracted",c:"Sentado, estira las rodillas para subir el rodillo hasta dejar las piernas rectas; aprieta el cu\xE1driceps arriba."},gim_extension_cuadriceps:{b:"shown from the side on a leg-extension machine, seated upright against the backrest, shins behind the ankle pad, knees extending fully to raise the pad to horizontal, quadriceps squeezed",c:"En la m\xE1quina, sube el rodillo estirando las rodillas del todo y baja despacio sin dejar caer el peso."},sf_curl_de_pierna_tumbado_en_maquina_de_femoral:{b:"shown from the side lying face-down on a lying leg-curl machine, the ankle pad behind the heels, curling the heels up toward the glutes, hips pressed into the pad, hamstrings contracted",c:"Boca abajo, lleva los talones hacia el gl\xFAteo sin despegar la cadera del banco; controla la vuelta."},sf_curl_de_piernas_sentado:{b:"shown from the side on a seated leg-curl machine, seated upright with a thigh pad over the legs, curling the ankle pad down and back under the seat by bending the knees, hamstrings contracted",c:"Sentado, flexiona las rodillas llevando el rodillo hacia abajo y atr\xE1s; aprieta el femoral al final."},sf_elevaciones_de_biceps_femoral_con_maquina_ghd:{b:"shown from the side on a glute-ham developer, thighs on the pad and feet anchored, lowering the straight torso forward then curling back up using the hamstrings, whole body rigid, a Nordic-style hamstring raise",c:"Con los pies fijos, baja el cuerpo recto al frente y sube frenando con el femoral; mant\xE9n el tronco firme."},gim_curl_femoral_sentado:{b:"shown from the side on a seated leg-curl machine, back against the pad and a lap pad securing the thighs, bending the knees to sweep the ankle pad down and under, hamstrings squeezing",c:"Sentado y bien sujeto, dobla las rodillas llevando el rodillo abajo y aprieta el femoral en el punto final."},sf_prensa_de_piernas:{b:"shown from the side on a 45\xB0 leg-press machine, reclined against the seat, both feet flat on the angled platform shoulder-width, knees bent toward the chest at the bottom about to press the sled away, quads and glutes loaded",c:"Pies a la anchura de hombros en la plataforma; baja hasta 90\xB0 sin despegar la zona lumbar y empuja sin bloquear de golpe."},sf_abducciones_de_cadera_sentado_con_banda:{b:"shown from the front seated on a bench with a mini band around the thighs just above the knees, pressing both knees apart OUT against the band, torso upright, glute medius working",c:"Sentado con la banda sobre las rodillas, \xE1brelas hacia fuera contra la goma y vuelve despacio."},sf_abduccion_de_cadera_con_maquina_de_abduccion_de_cadera:{b:"shown from the front seated on a hip-abduction machine, back against the pad, outer thighs against the moving pads, pressing both knees outward against the resistance, glute medius contracted",c:"En la m\xE1quina, empuja las rodillas hacia fuera contra los apoyos y controla el cierre."},sf_abduccion_con_polea:{b:"shown from the front standing tall beside a low cable with an ankle strap, sweeping one straight leg out to the side away from the midline against the cable, torso stable, outer hip working",c:"De pie junto a la polea con el cable en el tobillo; separa la pierna recta hacia el lateral sin inclinar el tronco."},sf_contragolpe_con_cable:{b:"shown from the side facing a low cable with an ankle strap, torso hinged slightly forward, driving one straight leg backward and up behind the body against the cable, glute maximus squeezed at the top",c:"De cara a la polea, lleva la pierna recta hacia atr\xE1s y arriba apretando el gl\xFAteo; no arquees la lumbar."},press_banca_barra:{b:"shown from the side mid-rep of a flat barbell bench press, lying supine on a bench with feet planted and a slight arch, an olympic barbell pressed up over the mid-chest, elbows tucked around 45\u201375\xB0, forearms vertical",c:"Tumbado, baja la barra al pecho con los codos a unos 45\xB0 y empuja hasta estirar sobre la l\xEDnea del pecho."},sf_press_de_banca_con_barra:{b:"shown from the side mid-rep of a flat barbell bench press, supine on a bench, shoulder blades pinched, barbell over the sternum, elbows at about 45\xB0, forearms vertical, chest and triceps driving",c:"Om\xF3platos juntos y pies firmes; baja al estern\xF3n y empuja recto sin rebotar la barra."},sf_press_banca_inclinado_con_mancuernas:{b:"shown from the side mid-rep of an incline dumbbell press on a 30\u201345\xB0 bench, back reclined, a dumbbell in each hand pressed up and slightly together over the UPPER chest, elbows under the wrists",c:"Banco inclinado; presiona las mancuernas hacia arriba y algo juntas trabajando la parte alta del pecho."},sf_press_de_banca_inclinado_con_barra:{b:"shown from the side mid-rep of an incline barbell press on a 30\u201345\xB0 bench, torso reclined, barbell pressed over the upper chest and collarbones, elbows tucked, upper pecs emphasised",c:"En banco inclinado, baja la barra a la clav\xEDcula y empuja arriba; enfatiza el pecho superior."},sf_press_de_banca_con_mancuernas:{b:"shown from the side mid-rep of a flat dumbbell bench press, supine on a flat bench, a dumbbell in each hand pressed up over the mid-chest, elbows about 45\xB0, wrists stacked over elbows",c:"Tumbado en banco plano, baja las mancuernas a los lados del pecho y empuja arriba junt\xE1ndolas ligeramente."},sf_press_de_banca_en_maquina_sentado:{b:"shown from the side seated upright on a chest-press machine, back against the pad, hands on the horizontal handles at chest level, pressing them straight forward to near-lockout, pecs engaged",c:"Sentado con la espalda apoyada; empuja las asas al frente a la altura del pecho y vuelve controlando."},sf_press_de_banca_declinado_con_barra:{b:"shown from the side mid-rep of a decline barbell press on a head-down decline bench, feet anchored, barbell pressed over the LOWER chest, elbows tucked, lower pecs working",c:"Banco declinado (cabeza abajo); baja la barra al pecho bajo y empuja, enfatizando la parte inferior del pectoral."},sf_press_de_banca_declinado_con_mancuernas:{b:"shown from the side mid-rep of a decline dumbbell press on a head-down decline bench, a dumbbell in each hand pressed over the lower chest, elbows tucked, lower pecs emphasised",c:"En banco declinado, presiona las mancuernas sobre la parte baja del pecho y controla la bajada."},sf_press_banca_con_agarre_cerrado:{b:"shown from the side mid-rep of a close-grip barbell bench press, supine on a flat bench, hands set narrow about shoulder-width, elbows tucked tight to the ribs, bar over the lower chest, triceps driving the press",c:"Agarre estrecho (anchura de hombros) y codos pegados al cuerpo; el empuje sale del tr\xEDceps."},press_mancuernas:{b:"shown from the side mid-rep of a flat dumbbell bench press, supine on a bench, a dumbbell in each hand pressed up over the mid-chest, elbows about 45\xB0, forearms vertical, chest and shoulders working",c:"Tumbado, baja las mancuernas a los lados del pecho con los codos a 45\xB0 y empuja arriba con control."},sf_aperturas_en_maquina_peck_deck_o_contractora:{b:"shown from the front seated on a pec-deck machine, back on the pad, forearms or handles against the vertical pads with a slight elbow bend, arcing the arms together in front of the chest, pecs squeezing",c:"Sentado, junta los brazos al frente en arco con el codo algo flexionado y aprieta el pecho; abre despacio."},sf_cruce_de_poleas:{b:"shown from the front standing between two high cable pulleys, a handle in each hand, arms sweeping down and together in a wide arc in front of the hips with a soft elbow bend, chest in a slight forward lean, pecs squeezed",c:"De pie entre dos poleas altas, junta las manos al frente en arco amplio con una ligera inclinaci\xF3n; aprieta el pecho."},sf_aperturas_con_mancuernas:{b:"shown from the front lying supine on a flat bench, a dumbbell in each hand held above the chest, arms opening WIDE out to the sides in a smooth arc with a fixed soft elbow bend, pecs stretching, then a controlled squeeze",c:"Tumbado, abre los brazos en cruz con el codo fijo y algo flexionado, siente el estiramiento y junta arriba."},sf_aperturas_inclinadas_con_mancuernas:{b:"shown from the front lying back on a 30\u201345\xB0 incline bench, a dumbbell in each hand opening wide in an arc over the upper chest with a fixed soft elbow bend, upper pecs stretched then squeezed",c:"Banco inclinado; abre en cruz con el codo semiflexionado enfatizando el pecho alto y junta arriba."},flexiones:{b:"shown from the side at the bottom of a push-up, one straight rigid line from head to heels, hands under the shoulders, elbows bent back to about 45\xB0, chest hovering just above the floor, core braced",c:"Cuerpo en l\xEDnea recta de cabeza a talones; baja el pecho al suelo con los codos a 45\xB0 y empuja."},sf_plancha_con_flexion:{b:"shown from the side mid push-up rising out of a plank, body in one rigid straight line from head to heels, hands under the shoulders, elbows bending back, core and glutes braced throughout",c:"Desde plancha, baja el pecho en flexi\xF3n sin arquear la lumbar y sube; mant\xE9n el cuerpo recto y firme."},press_militar:{b:"shown from the front at lockout of a standing strict overhead press, an olympic barbell pressed straight up over the crown of the head, wrists stacked over elbows over shoulders, ribs down, glutes and core braced",c:"De pie, aprieta gl\xFAteo y abdomen y empuja la barra recta por encima de la cabeza hasta bloquear."},sf_press_de_hombro_con_mancuernas:{b:"shown from the front at lockout of a seated dumbbell shoulder press, a dumbbell in each hand pressed up overhead until they nearly touch, wrists over elbows, torso upright, deltoids working",c:"Sube las mancuernas por encima de la cabeza hasta casi tocarlas, sin arquear la espalda."},sf_press_de_hombros_en_maquina_smith:{b:"shown from the front pressing a Smith-machine bar overhead from shoulder height, the guided bar traveling straight up in its rails, seated or standing upright, wrists stacked over the bar, deltoids driving",c:"Empuja la barra guiada recta hacia arriba desde los hombros; mant\xE9n el tronco firme y no bloquees de golpe."},sf_press_militar_con_mancuernas:{b:"shown from the front at lockout of a standing dumbbell military press, a dumbbell in each hand driven overhead, ribs down and core tight, arms nearly straight, side and front deltoids working",c:"De pie, empuja las mancuernas sobre la cabeza con el core apretado y sin llevar la carga por delante."},sf_press_militar_sentado_con_barra:{b:"shown from the front seated upright on a bench with back support, pressing an olympic barbell from the collarbones straight up overhead to lockout, wrists over elbows, deltoids and triceps working",c:"Sentado con respaldo, sube la barra desde la clav\xEDcula recta sobre la cabeza y baja controlando."},sf_press_tras_nuca_sentado:{b:"shown from the front seated upright pressing a barbell overhead from BEHIND the neck, lowering the bar to the base of the neck with wide elbows then pressing to lockout, upright torso, rear deltoids emphasised",c:"Sentado, baja la barra por detr\xE1s hasta la nuca con los codos abiertos y sube; requiere buena movilidad de hombro."},sf_press_militar_de_pie:{b:"shown from the front at lockout of a standing barbell overhead press, bar pressed from the collarbones straight up over the head, ribs down, glutes and core braced, wrists stacked over elbows",c:"De pie con el core firme, empuja la barra desde los hombros hasta arriba y mete la cabeza al final."},sf_press_militar_de_pie_tras_nuca:{b:"shown from the front standing and pressing a barbell overhead from BEHIND the neck, lowering to the base of the neck with wide elbows then locking out overhead, tall torso",c:"De pie, baja la barra tras la nuca con codos abiertos y empuja arriba; controla el rango con buena movilidad."},gim_press_hombro_maquina:{b:"shown from the front seated on a shoulder-press machine, back against the pad, hands on the handles at shoulder height, pressing them straight up overhead to near-lockout, deltoids working",c:"Sentado y apoyado, empuja las asas rectas hacia arriba desde los hombros y baja con control."},fondos_triceps:{b:"shown from the side at the bottom of parallel-bar triceps dips, supporting the body on two parallel bars, torso fairly upright, elbows bent back to about 90\xB0 with the chest lowered between the bars, triceps loaded",c:"En paralelas con el tronco vertical, baja hasta 90\xB0 de codo pegando los brazos al cuerpo y empuja arriba."},sf_extension_de_triceps_tumbado:{b:"shown from the side lying supine on a bench performing a lying triceps extension (skull-crusher), upper arms vertical and fixed, only the forearms lowering the weight toward the forehead then extending, triceps working",c:"Tumbado, mant\xE9n los codos quietos apuntando al techo y baja el peso hacia la frente doblando solo el antebrazo."},sf_extension_de_triceps_en_polea:{b:"shown from the front at a high cable performing a straight-bar triceps push-down, tall torso, upper arms pinned to the sides, only the forearms extending down to push the bar to full lockout, triceps squeezed",c:"Codos pegados al costado; empuja la barra hacia abajo estirando solo el antebrazo y aprieta el tr\xEDceps abajo."},sf_extension_de_triceps_en_polea_con_cuerda:{b:"shown from the front at a high cable doing a rope triceps push-down, upper arms fixed to the sides, pressing a rope down and spreading the two ends apart at the bottom, elbows fully extended, triceps contracted",c:"Con la cuerda, baja y separa los extremos al final estirando el codo del todo; codos quietos junto al cuerpo."},sf_extension_de_triceps_con_mancuernas_por_encima_de_la_cabeza:{b:"shown from the side performing an overhead dumbbell triceps extension, one dumbbell held with both hands above the head, upper arms vertical beside the ears, lowering the weight behind the head then extending, long head stretched",c:"Mancuerna sobre la cabeza; baja tras la nuca doblando solo los codos (que apuntan arriba) y estira el brazo."},sf_extension_de_triceps_con_cable_de_agarre_inverso_con_barra:{b:"shown from the front at a high cable doing a reverse-grip (underhand) triceps push-down with a straight bar, palms facing up, upper arms fixed, forearms extending the bar down, medial triceps emphasised",c:"Agarre inverso (palmas arriba) en la barra; empuja hacia abajo con los codos fijos estirando el antebrazo."},sf_extension_de_triceps_con_cable_a_una_mano:{b:"shown from the front at a high cable performing a single-arm triceps push-down with an overhand grip on a small handle, upper arm pinned to the side, forearm extending down to full lockout, triceps squeezed",c:"A una mano, empuja el agarre hacia abajo con el codo pegado al costado y aprieta el tr\xEDceps al estirar."},sf_extension_de_triceps_con_mancuernas_tumbado:{b:"shown from the side lying supine on a bench doing lying dumbbell triceps extensions, a dumbbell in each hand, upper arms vertical and still, forearms lowering the weights toward the head then extending, triceps working",c:"Tumbado con una mancuerna en cada mano, baja hacia la cabeza moviendo solo el antebrazo y estira arriba."},sf_press_frances_sentado_con_barra:{b:"shown from the side seated on a bench performing a seated French press, an EZ or straight barbell held overhead, upper arms vertical beside the head, lowering the bar behind the head by bending only the elbows, then extending",c:"Sentado, baja la barra por detr\xE1s de la cabeza doblando solo los codos (que miran al techo) y estira arriba."},sf_fondos_en_banco:{b:"shown from the side performing bench dips, hands on the edge of a bench behind the hips, legs out front, lowering the hips toward the floor by bending the elbows back to 90\xB0, then pressing up, triceps working",c:"Manos en el borde del banco tras la cadera; baja el cuerpo doblando los codos hacia atr\xE1s y empuja arriba."},sf_fondos_en_barras_paralelas:{b:"shown from the side at the bottom of parallel-bar dips, body supported on two bars, elbows bent back to about 90\xB0, torso fairly upright for triceps emphasis, shoulders down, about to press to lockout",c:"En paralelas, baja hasta 90\xB0 con el tronco vertical y empuja hasta estirar los brazos; hombros abajo."},gim_extension_triceps_maquina:{b:"shown from the side on an assisted-dip machine, kneeling on the assistance pad and gripping the parallel handles, lowering into a dip with the torso upright then pressing up, triceps working",c:"En la m\xE1quina de fondos asistidos, baja con el tronco recto y empuja hasta estirar; la rodilla en el apoyo ayuda."},sf_elevacion_lateral_con_mancuernas:{b:"shown from the front at the top of a dumbbell lateral raise, a dumbbell in each hand lifted out to the sides to shoulder height with a slight elbow bend, wrists no higher than the elbows, side deltoids working",c:"Sube las mancuernas en cruz hasta la altura del hombro con el codo algo doblado, sin encoger el trapecio."},sf_elevacion_lateral_con_cable_a_una_mano:{b:"shown from the front standing beside a low cable, lifting one arm out to the side to shoulder height against the cable with a slight elbow bend, torso still, one side deltoid working",c:"Junto a la polea baja, sube un brazo al lateral hasta el hombro contra el cable, con el tronco quieto."},sf_elevacion_frontal_con_mancuernas:{b:"shown from the side at the top of a dumbbell front raise, lifting a dumbbell straight forward to shoulder height with a nearly straight arm, tall posture, front deltoid working",c:"Sube la mancuerna al frente con el brazo casi recto hasta la altura del hombro; no balancees el tronco."},sf_elevaciones_frontales_con_cable_a_una_mano:{b:"shown from the side standing in front of a low cable, raising one straight arm forward and up to shoulder height against the cable, torso stable, front deltoid working",c:"De espaldas a la polea baja, sube el brazo recto al frente hasta el hombro contra el cable, sin impulso."},sf_elevaciones_frontales_con_barra:{b:"shown from the side at the top of a barbell front raise, both hands on a barbell lifted straight forward to shoulder height with nearly straight arms, tall torso, front deltoids working",c:"Sube la barra al frente con los brazos casi rectos hasta la altura del hombro, sin balanceo."},sf_elevacion_frontal_con_mancuernas_alternas_agarre_neutro:{b:"shown from the side performing alternating neutral-grip dumbbell front raises, palms facing each other, lifting one dumbbell forward to shoulder height while the other rests, tall posture, front deltoids working",c:"Agarre neutro (palmas enfrentadas); sube una mancuerna al frente y luego la otra, alternando sin impulso."},sf_elevacion_frontal_con_un_brazo_en_polea_baja_agarre_neutro:{b:"shown from the side raising one arm forward to shoulder height with a neutral-grip handle on a low cable, palm facing in, torso stable, front deltoid working against the cable",c:"Con agarre neutro en polea baja, sube un brazo al frente hasta el hombro manteniendo el tronco firme."},sf_elevacion_frontal_con_mancuerna_a_dos_manos:{b:"shown from the front raising a single dumbbell held vertically with BOTH hands straight forward to shoulder height, arms nearly straight, tall posture, front deltoids working",c:"Sujeta una mancuerna con las dos manos y s\xFAbela al frente hasta el hombro con los brazos casi rectos."},sf_encogimiento_de_hombros_con_barra:{b:"shown from the front at the top of a barbell shrug, standing tall holding a barbell at arm's length in front of the thighs, shoulders lifted straight up toward the ears, arms relaxed and straight, traps contracted",c:"Barra colgando delante; sube los hombros rectos hacia las orejas sin doblar los codos y aprieta el trapecio."},sf_encogimiento_de_hombros_con_mancuernas:{b:"shown from the front at the top of a dumbbell shrug, a dumbbell in each hand hanging at the sides, shoulders elevated straight up toward the ears, arms straight and relaxed, traps squeezed",c:"Mancuernas a los lados; eleva los hombros rectos hacia las orejas y baja despacio, sin girarlos."},remo_barra:{b:"shown from the side performing a bent-over barbell row, torso hinged to near-parallel with a flat back, knees soft, pulling an olympic barbell to the lower ribs with the elbows driving back past the torso, lats squeezing",c:"Tronco inclinado y espalda recta; lleva la barra al abdomen bajo tirando con los codos hacia atr\xE1s."},remo_mancuerna:{b:"shown from the side performing a single-arm dumbbell row, one hand and knee braced on a bench, flat back parallel to the floor, rowing a dumbbell up to the hip with the elbow close to the body, lat contracting",c:"Apoya mano y rodilla en el banco; rema la mancuerna hacia la cadera con el codo pegado, sin girar el tronco."},sf_remo_con_mancuerna_a_una_mano:{b:"shown from the side doing a single-arm dumbbell row with one hand and knee on a bench, flat back, pulling the dumbbell up along the ribs to the hip, elbow tight to the side, lat squeezed at the top",c:"Con apoyo en el banco y espalda plana, tira de la mancuerna hacia la cadera y aprieta la espalda arriba."},sf_remo_en_maquina:{b:"shown from the side seated at a chest-supported row machine, chest against the pad, gripping the handles and pulling them back to the ribs with the elbows driving behind the torso, shoulder blades retracting",c:"Pecho apoyado; tira de las asas hacia las costillas juntando los om\xF3platos, sin encoger los hombros."},sf_remo_en_barra_t:{b:"shown from the side performing a T-bar row, straddling a landmine bar, torso hinged forward with a flat back, pulling the loaded end and handles up to the chest with elbows back, mid-back squeezing",c:"Inclinado sobre la barra T, tira el peso hacia el pecho con los codos atr\xE1s y la espalda recta."},sf_elevaciones_en_barra_fija:{b:"shown from the front at the top of a pull-up on a fixed overhead bar, overhand shoulder-width grip, chin above the bar, shoulder blades pulled down and together, elbows driven to the ribs, lats and biceps working",c:"Agarre prono; tira hasta subir la barbilla sobre la barra bajando los om\xF3platos, sin balanceo."},sf_elevaciones_tras_nuca_en_barra_fija:{b:"shown from the front at the top of a behind-the-neck pull-up on a fixed bar, wide overhand grip, pulling the body up until the bar passes behind the base of the neck, elbows wide, upper back working",c:"Agarre ancho; sube llevando la nuca hacia la barra con los codos abiertos (requiere buena movilidad)."},sf_remo_inclinado_con_mancuernas:{b:"shown from the side doing a bent-over two-dumbbell row, torso hinged to near-parallel with a flat back, a dumbbell in each hand rowed up to the lower ribs with elbows driving back, lats squeezing",c:"Inclinado con la espalda recta; sube ambas mancuernas al abdomen tirando con los codos hacia atr\xE1s."},sf_remo_alto_con_barra:{b:"shown from the front at the top of an upright row, standing tall pulling a barbell straight up the front of the body to chest height with the elbows leading high and wide, shoulders and traps working",c:"Sube la barra pegada al cuerpo hasta el pecho con los codos altos por delante; hombros y trapecio."},gim_remo_sentado_polea:{b:"shown from the side seated at a low cable row with a triangle handle, tall chest and slight lean, pulling the handle to the navel with the elbows driving straight back, shoulder blades retracting, lats engaged",c:"Sentado con el pecho alto, lleva el agarre al ombligo tirando con los codos atr\xE1s y juntando la espalda."},sf_remo_inclinado_con_barra_con_agarre_supinado:{b:"shown from the side doing a bent-over barbell row with a SUPINATED underhand grip (Yates style), torso hinged with a flat back, elbows tucked close, pulling the bar to the lower abdomen, lower lats and biceps working",c:"Agarre supino (palmas al frente) y codos pegados; tira de la barra al abdomen bajo con la espalda recta."},sf_elevaciones_en_barra_fija_con_agarre_supinado:{b:"shown from the front at the top of a chin-up on a fixed bar, SUPINATED underhand shoulder-width grip, chin above the bar, elbows driving down to the ribs, biceps and lats fully engaged",c:"Agarre supino a la anchura de hombros; sube la barbilla sobre la barra; el b\xEDceps participa m\xE1s."},gim_dominada_supina:{b:"shown from the front at the top of a chin-up, SUPINATED underhand grip about shoulder-width, chin above the fixed bar, elbows tucked and driving down, biceps and lats working",c:"Palmas hacia ti; tira hasta pasar la barbilla la barra con los codos hacia el cuerpo, sin impulso."},jalon_banda:{b:"shown from the front kneeling or seated pulling a resistance band anchored overhead down to the upper chest, elbows driving down and back, torso tall with a slight lean, lats engaged",c:"Con la banda anclada arriba, tira de ella al pecho llevando los codos abajo y atr\xE1s; abre el pecho."},sf_jalon_con_agarre_ancho:{b:"shown from the front seated at a lat-pulldown machine with a WIDE overhand grip, tall chest and slight lean back, driving the elbows down to bring the bar to the upper chest, lats fully engaged",c:"Agarre ancho; lleva la barra al pecho tirando con los codos abajo, sin balancear el tronco atr\xE1s."},sf_jalon_al_pecho_con_agarre_cerrado:{b:"shown from the front seated at a lat pulldown with a CLOSE grip on a narrow handle, chest tall, pulling the handle to the upper chest with the elbows driving straight down close to the body, lats working",c:"Agarre cerrado; tira del agarre al pecho con los codos pegados y baja despacio controlando."},sf_jalon_tras_nuca:{b:"shown from the front seated at a lat pulldown, wide overhand grip, pulling the bar down BEHIND the neck to the base of the skull with wide elbows, upright torso, upper back working",c:"Agarre ancho; baja la barra por detr\xE1s hasta la nuca con los codos abiertos (solo con buena movilidad)."},sf_jalon_al_pecho_con_agarre_invertido:{b:"shown from the front seated at a lat pulldown with a SUPINATED underhand shoulder-width grip, pulling the bar to the upper chest with the elbows driving down and back close to the body, lats and biceps working",c:"Agarre supino a la anchura de hombros; lleva la barra al pecho con los codos pegados; participa el b\xEDceps."},sf_jalon_en_polea_con_cuerda:{b:"shown from the front seated at a high pulley pulling a rope down to the chest, splitting the rope ends apart at the bottom, elbows driving down and back, lats and rear shoulders working",c:"Con la cuerda, baja separando los extremos al final y lleva los codos abajo y atr\xE1s."},sf_jalon_dorsal_con_brazos_rectos:{b:"shown from the side standing at a high cable performing a straight-arm pulldown, a slight forward lean, arms kept nearly straight sweeping a bar down from overhead to the thighs in a wide arc, lats contracting",c:"De pie, con los brazos casi rectos, baja la barra desde arriba hasta los muslos en arco; a\xEDsla el dorsal."},sf_pullover_con_mancuerna:{b:"shown from the side lying across or along a bench doing a dumbbell pullover, a single dumbbell held with both hands, arms nearly straight lowering it back behind the head in an arc then pulling it over the chest, lats and chest stretched",c:"Tumbado, baja la mancuerna por detr\xE1s de la cabeza con los brazos casi rectos y s\xFAbela sobre el pecho."},sf_pullover_con_barra:{b:"shown from the side lying supine on a bench doing a barbell pullover, arms nearly straight lowering the barbell behind the head in an arc then arcing it back over the chest, ribcage expanded, lats stretched",c:"Tumbado, lleva la barra por detr\xE1s de la cabeza con los brazos casi rectos y devu\xE9lvela sobre el pecho."},gim_jalon_neutro:{b:"shown from the front seated at a lat pulldown with a NEUTRAL parallel-grip handle, palms facing each other, pulling the handle to the upper chest with the elbows driving straight down, lats working",c:"Agarre neutro (palmas enfrentadas); tira al pecho con los codos abajo y junta un poco los om\xF3platos."},gim_jalon_unilateral:{b:"shown from the front seated at a high pulley pulling a single handle down with ONE arm, allowing a slight trunk rotation, elbow driving down to the ribs, one lat fully stretching and contracting",c:"A un brazo; estira arriba y tira del agarre a la costilla permitiendo un peque\xF1o giro del tronco."},gim_pullover_polea:{b:"shown from the side standing facing a high pulley with a straight bar, torso slightly hinged, arms kept straight sweeping the bar down from overhead to the thighs, lats contracting through a long arc",c:"De pie frente a la polea alta, con brazos rectos lleva la barra desde arriba hasta los muslos aislando el dorsal."},dominadas:{b:"shown from the front at the top of a pull-up hanging from a fixed overhead bar, overhand grip, chin above the bar, shoulder blades pulled down and together, elbows driven to the ribs, lats and biceps working",c:"Agarre prono; cuelga con los brazos estirados y sube la barbilla sobre la barra bajando los om\xF3platos."},escalada_roco:{b:"shown from the side climbing a bouldering wall, reaching one hand up to a hold while the opposite foot presses on a foothold, hips close to the wall, body in a controlled diagonal, forearms and back working",c:"Mant\xE9n la cadera cerca de la pared y empuja con las piernas; los brazos gu\xEDan, no cargan todo el peso."},escalada_travesia:{b:"shown from the side traversing sideways across a climbing wall, arms reaching laterally to holds and legs spread wide for balance, hips low and close to the wall, whole body engaged",c:"Despl\xE1zate lateralmente con pasos cortos y la cadera baja pegada a la pared; reparte el peso en los pies."},gim_dominada_neutra:{b:"shown from the front at the top of a pull-up on parallel neutral-grip handles, palms facing each other, chin at hand height, elbows driving down to the ribs, lats and biceps working",c:"Agarre neutro (palmas enfrentadas); sube con los codos hacia el cuerpo, m\xE1s c\xF3modo para el hombro."},gim_dominada_lastrada:{b:"shown from the front at the top of a weighted pull-up, a weight plate hanging from a dip belt at the waist, overhand grip, chin above the bar, controlled and strong, lats and biceps loaded",c:"Con lastre en el cintur\xF3n, haz dominadas estrictas de rango completo; a\xF1ade peso solo si dominas la t\xE9cnica."},gim_dominada_asistida:{b:"shown from the front performing an assisted pull-up, a resistance band looped under one foot (or an assist-machine knee pad) helping the ascent, overhand grip, chin rising toward the bar, lats working",c:"La banda bajo el pie o la m\xE1quina te ayuda a subir; controla la bajada completa para ganar fuerza."},gim_dominada_negativa:{b:"shown from the front at the top of a pull-up about to lower SLOWLY, chin above the bar having stepped up from a box, overhand grip, controlling a slow descent to full hang, lats loaded eccentrically",c:"Sube ayud\xE1ndote de un caj\xF3n y baja lo m\xE1s lento posible hasta estirar del todo; entrena la fase exc\xE9ntrica."},curl_biceps:{b:"shown from the front at peak contraction of a standing dumbbell biceps curl, tall torso, upper arms pinned to the sides, elbows flexed to bring the weights toward the shoulders, wrists supinated, biceps squeezed",c:"Codos pegados al costado; sube girando la palma hacia arriba y baja controlado sin balancear el torso."},sf_curl_con_barra:{b:"shown from the front at peak contraction of a standing barbell curl, both hands underhand on a straight bar, upper arms fixed to the sides, curling the bar up to the shoulders, biceps contracted, wrists neutral",c:"Con la barra recta y los codos quietos, sube hasta el pecho sin usar impulso de la espalda; baja despacio."},sf_curl_alterno_con_mancuernas:{b:"shown from the front performing alternating dumbbell curls, one arm curling a dumbbell up while supinating the wrist as it rises, the other arm relaxed at the side, upper arms fixed, biceps working",c:"Sube una mancuerna girando la palma hacia arriba y luego la otra, alternando con los codos pegados."},sf_curl_con_cuerda_en_polea:{b:"shown from the front at a low cable curling a rope or handle up toward the shoulders, upper arms pinned to the sides, elbows flexing against constant cable tension, biceps squeezed",c:"En polea baja, sube el agarre hacia los hombros con los codos fijos; la tensi\xF3n del cable es constante."},sf_curl_con_barra_ez:{b:"shown from the front at peak contraction of a standing EZ-bar curl, hands on the angled grips of an EZ bar in a semi-supinated position, upper arms fixed, curling to the shoulders, biceps contracted",c:"Con la barra EZ, agarra las inclinaciones (m\xE1s c\xF3modo para la mu\xF1eca) y sube con los codos quietos."},sf_curl_de_predicador_con_barra_ez:{b:"shown from the side performing a preacher curl, the backs of the upper arms resting flat on the angled preacher pad, curling an EZ bar up from a full stretch at the bottom to the top, biceps isolated",c:"Brazos apoyados en el banco Scott; baja hasta estirar del todo y sube sin despegar los codos del apoyo."},sf_curl_alterno_de_martillo_con_mancuernas:{b:"shown from the front performing an alternating hammer curl, NEUTRAL grip with palms facing each other (thumbs up), curling one dumbbell up with the wrist staying vertical, brachialis and forearms working",c:"Agarre de martillo (palmas enfrentadas); sube sin girar la mu\xF1eca, alternando brazos; trabaja braquial y antebrazo."},sf_curl_inclinado_con_mancuernas:{b:"shown from the side lying back on an incline bench doing incline dumbbell curls, upper arms hanging BEHIND the torso for a big stretch, curling the dumbbells up while supinating, long head of the biceps stretched",c:"Recostado en banco inclinado con los brazos colgando atr\xE1s; sube desde el estiramiento girando la palma."},sf_curl_concentrado_con_mancuernas:{b:"shown from the side seated leaning forward, the back of one upper arm braced against the inner thigh, curling a single dumbbell up to the shoulder in strict isolation, biceps peak contracted",c:"Sentado, apoya el codo en la cara interna del muslo y sube la mancuerna aislando el b\xEDceps, sin mover el brazo."},sf_curl_de_cable_en_polea_baja_a_una_mano:{b:"shown from the front standing at a low cable curling a single handle up with ONE arm, upper arm pinned to the side, wrist supinating, constant cable tension, one biceps contracting",c:"A un brazo en polea baja, sube el agarre girando la palma con el codo fijo; tensi\xF3n continua del cable."},sf_curl_de_cable_con_barra_recta_en_polea_baja:{b:"shown from the front standing at a low cable with a straight bar, curling it up to the shoulders with both hands, upper arms fixed to the sides, wrists neutral, biceps under constant tension",c:"Con barra recta en polea baja, sube hasta el pecho con los codos quietos; la tensi\xF3n no se pierde abajo."},sf_curl_de_cable_en_polea_alta_de_pie:{b:"shown from the front standing between two high pulleys, arms out to the sides at shoulder height, curling both handles in toward the head in a double-biceps pose, peak contraction squeezed",c:"Brazos abiertos a la altura del hombro entre dos poleas altas; flexiona llevando los pu\xF1os a la cabeza y aprieta."},sf_curl_de_muneca_con_barra_sentado:{b:"shown from the side seated with the forearms resting on the thighs, palms UP holding a barbell, wrists hanging off the knees and curling up by flexing only the wrists, forearm flexors working",c:"Antebrazos sobre los muslos y palmas arriba; sube la barra flexionando solo la mu\xF1eca para trabajar el antebrazo."},sf_curl_de_barra_invertido:{b:"shown from the front at peak contraction of a reverse curl, PRONATED overhand grip on a barbell, upper arms fixed, curling the bar up with the knuckles leading, brachioradialis and forearm extensors working",c:"Agarre prono (nudillos arriba); sube la barra con los codos pegados para trabajar antebrazo y braquial."},reverse_fly:{b:"shown from the side hinged forward with a flat back, a light dumbbell in each hand hanging below the chest, arms sweeping wide OUT and up in a reverse arc with soft elbows, rear deltoids and mid-back squeezing",c:"Inclinado con la espalda recta, abre los brazos en cruz hacia los lados apretando el hombro posterior."},sf_cruces_inversos_en_polea_alta:{b:"shown from the front standing between two HIGH pulleys with arms crossed, a handle in each hand, sweeping the arms apart OUT and back at shoulder height in a wide reverse arc, rear deltoids working",c:"Entre dos poleas altas con los brazos cruzados, \xE1brelos hacia atr\xE1s a la altura del hombro; hombro posterior."},sf_elevaciones_posteriores_para_hombros_pajaro:{b:"shown from the side hinged forward at the hips with a flat back (bent-over 'bird' raise), arms hanging down then lifting out to the sides to shoulder height with a slight elbow bend, rear deltoids working",c:"Inclinado al frente, sube los brazos abiertos en cruz hasta la altura del hombro; aprieta el deltoides posterior."},gim_face_pull:{b:"shown from the front performing a cable face pull, pulling a rope toward the eyes/forehead with the elbows flaring high and wide, shoulder blades retracted, rear deltoids and upper back working",c:"Tira de la cuerda hacia la cara con los codos altos y abiertos, juntando los om\xF3platos; hombro posterior y trapecio."},plancha:{b:"shown from the side holding a forearm plank, forearms flat on the floor under the shoulders, body one perfectly straight rigid line from head to heels, hips level, core and glutes braced, neck neutral",c:"Antebrazos bajo los hombros y cuerpo en l\xEDnea recta; aprieta abdomen y gl\xFAteo sin subir ni hundir la cadera."},plancha_lateral:{b:"shown from the front holding a side plank, propped on one forearm with the body stacked in a straight diagonal line, hips lifted high, feet stacked, the top arm reaching up or on the hip, obliques bracing",c:"Apoyo en un antebrazo con el cuerpo en l\xEDnea; sube la cadera y no dejes que caiga hacia el suelo."},pallof_press:{b:"shown from the front standing side-on to a cable or band at chest height, pressing the handle straight out from the sternum with both hands and resisting the sideways pull, torso squared and stiff, anti-rotation core braced",c:"De lado a la polea, saca las manos al frente resistiendo el giro; el abdomen impide que el tronco rote."},bird_dog:{b:"shown from the side on all fours, simultaneously extending one arm straight forward and the OPPOSITE leg straight back to horizontal in line with the flat back, hips level, core stable, a balanced hold",c:"A cuatro apoyos, estira brazo y pierna contrarios hasta la horizontal sin girar la cadera; mant\xE9n el equilibrio."},snowboard_equilibrio:{b:"shown from the front in a low athletic side-on stance as if on a snowboard, knees bent and hips loaded, arms out for balance, weight shifting laterally over a stable base, core and legs working",c:"Postura lateral con rodillas flexionadas; desplaza el peso de lado a lado manteniendo el centro estable."},sf_plancha:{b:"shown from the side holding a forearm plank, forearms under the shoulders, body a straight rigid line from head to heels, hips neither sagging nor piked, core braced",c:"Cuerpo recto de cabeza a talones sobre los antebrazos; mete el ombligo y aprieta el gl\xFAteo, respira."},gim_plancha_lastrada:{b:"shown from the side holding a forearm plank with a weight plate resting on the upper back, body one straight rigid line from head to heels, core braced hard against the added load",c:"Plancha con un disco en la espalda alta; mant\xE9n la l\xEDnea recta y el abdomen muy apretado sin arquear."},gim_hollow_hold:{b:"shown from the side holding a hollow-body position, lying supine with the lower back pressed flat into the floor, arms extended overhead and straight legs lifted, both ends curled up into a shallow banana shape, abs braced",c:"Tumbado, pega la lumbar al suelo y eleva brazos y piernas rectos; el cuerpo forma una leve U tensa."},gim_copenhagen:{b:"shown from the front holding a Copenhagen side plank, propped on one forearm with the TOP leg resting on a bench and the bottom leg lifted underneath toward it, body in a straight line, inner-thigh adductors bracing",c:"Antebrazo apoyado y la pierna de arriba sobre el banco; sube la cadera activando el aductor de la pierna baja."},dead_bug:{b:"shown from the side lying supine with arms reaching to the ceiling and hips and knees bent at 90\xB0 (tabletop), lowering one arm overhead and the OPPOSITE leg toward the floor while the low back stays flat, then switching, core braced",c:"Boca arriba con brazos y piernas a 90\xB0; baja brazo y pierna contrarios sin despegar la lumbar del suelo."},rotacion_toracica:{b:"shown from the side on all fours performing a thoracic rotation, one hand behind the head, rotating that elbow down under the body then opening it up toward the ceiling, hips still, the mid-back twisting through a wide arc",c:"A cuatro apoyos, mano en la nuca; abre el codo hacia el techo girando la parte alta de la espalda sin mover la cadera."},sf_crunch:{b:"shown from the side at the top of an abdominal crunch, lying on the back with knees bent and feet flat, curling only the shoulder blades off the floor toward the knees, lower back staying down, upper abs contracted",c:"Enrolla solo los hombros hacia las rodillas sin tirar del cuello; la lumbar no se despega del suelo."},sf_crunch_oblicuo:{b:"shown from the side at the top of an oblique crunch, lying on the back with knees bent, curling up and ACROSS bringing one shoulder toward the opposite knee, the twisting obliques contracted",c:"Lleva un hombro hacia la rodilla contraria girando el tronco; trabaja el oblicuo, sin tir\xF3n de cuello."},sf_abdominales_en_maquina:{b:"shown from the side seated on an ab-crunch machine, chest against the upper pad, crunching the torso forward and down against the resistance by contracting the abs, controlled return",c:"Sentado en la m\xE1quina, flexiona el tronco hacia delante con el abdomen y vuelve despacio, sin usar los brazos."},sf_abdominales_con_cuerda_en_polea_alta:{b:"shown from the side kneeling in front of a high cable holding a rope beside the head, crunching the torso down by rounding the spine and contracting the abs toward the floor, hips fixed, cable resisting",c:"De rodillas con la cuerda en la nuca, enrolla el tronco hacia abajo con el abdomen sin mover la cadera."},sf_elevacion_de_piernas:{b:"shown from the side lying supine with legs straight, raising both legs together up to vertical while the low back stays pressed to the floor, then lowering with control, lower abs working",c:"Tumbado, sube las piernas rectas hasta la vertical y b\xE1jalas lento sin despegar la lumbar del suelo."},gim_rueda_abdominal:{b:"shown from the side performing an ab-wheel rollout, kneeling and gripping a wheel, rolling it forward to extend the body into a long straight line just above the floor, bracing hard, then pulling back, whole core loaded",c:"De rodillas, rueda al frente estirando el cuerpo sin arquear la lumbar y vuelve con el abdomen muy apretado."},gim_elevacion_colgado:{b:"shown from the front hanging from a fixed overhead bar, raising both legs up in front of the body toward the chest with the pelvis curling under, lower abs and hip flexors working, minimal swing",c:"Colgado de la barra, sube las piernas al frente enrollando la pelvis, sin balancearte; controla la bajada."},gim_rotacion_polea:{b:"shown from the front standing side-on to a cable, arms extended holding the handle and sweeping it horizontally ACROSS the body in a rotational chop, hips fairly still while the trunk rotates powerfully, obliques working",c:"De lado a la polea, gira el tronco llevando las manos cruzadas al otro lado; la fuerza sale de los oblicuos."},gim_dead_bug_carga:{b:"shown from the side lying supine holding a light weight up toward the ceiling with both hands, hips and knees at 90\xB0, lowering one straight leg toward the floor while the arms stay fixed and the low back stays flat, core braced",c:"Como el dead bug pero sujetando una carga arriba con los brazos fijos; baja una pierna sin arquear la lumbar."},gim_bird_dog:{b:"shown from the side on all fours, extending one arm forward and the opposite leg back to horizontal in line with the flat spine, hips level and square, a slow controlled anti-rotation hold",c:"Estira brazo y pierna contrarios a la horizontal manteniendo la cadera nivelada; ni la dejes caer ni la gires."},sf_encogimientos_de_rodillas_para_abdominales:{b:"shown from the side seated on the floor leaning back on the hands with feet lifted, pulling both bent knees in toward the chest then extending the legs out straight, lower abs contracting, torso braced",c:"Sentado y algo reclinado, lleva las rodillas al pecho y estira las piernas al frente sin apoyar los pies."},sf_elevaciones_de_rodilla:{b:"shown from the front standing tall driving one knee up to hip height then quickly switching, torso upright, arms swinging as in a march, core and hip flexors working, a lively marching motion",c:"De pie, sube una rodilla a la altura de la cadera y alterna con ritmo, con el tronco erguido y el abdomen activo."},sf_ejercicio_superman_en_cuadrupedia:{b:"shown from the side on all fours extending the opposite arm and leg straight out (a quadruped 'superman'), reaching long to horizontal in line with the flat back, hips level and stable, a balanced hold",c:"A cuatro apoyos, estira brazo y pierna contrarios a la horizontal alargando el cuerpo; cadera firme y nivelada."},farmer_carry:{b:"shown from the front performing a farmer's carry, walking tall with a heavy dumbbell or kettlebell hanging in EACH hand at the sides, shoulders back and down, ribs stacked, braced core and firm grip",c:"Camina erguido con una carga pesada en cada mano; hombros atr\xE1s, abdomen firme y pasos cortos y estables."},gim_suitcase_carry:{b:"shown from the front performing a suitcase carry, walking tall with a single heavy weight in ONE hand at the side like a suitcase, resisting the sideways lean so the torso stays perfectly upright, obliques bracing",c:"Carga en un solo lado como una maleta; camina recto sin inclinarte, el abdomen evita que el tronco caiga."},sf_extension_de_muneca_con_barra_sentado:{b:"shown from the side seated with the forearms resting on the thighs, palms DOWN holding a barbell, wrists hanging off the knees and extending upward by lifting the knuckles, forearm extensors working",c:"Antebrazos sobre los muslos y palmas hacia abajo; sube la barra extendiendo solo la mu\xF1eca (nudillos arriba)."},sf_extension_de_triceps_con_cable_a_una_mano_con_agarre_supinado:{b:"shown from the front at a high cable performing a single-arm SUPINATED (underhand) triceps push-down, palm facing up, upper arm pinned to the side, forearm extending the handle down to full lockout, triceps squeezed",c:"A una mano con agarre supino (palma arriba); empuja hacia abajo con el codo pegado y aprieta el tr\xEDceps al estirar."},carrera_suave:{b:"shown from the side running at an easy relaxed jog, mid-stride with a gentle float phase, one knee lifting moderately, opposite arm forward, hands loose, tall calm posture, comfortable conversational effort",c:"Ritmo c\xF3modo en el que puedes hablar; zancada relajada, hombros sueltos y apoyo bajo el centro del cuerpo."},series_carrera:{b:"shown from the side running fast during an interval, strong stride with high knee drive and a pronounced float phase, arms pumping powerfully, forward lean, focused effort at near-maximal pace",c:"Tramos r\xE1pidos y fuertes con recuperaci\xF3n entre ellos; corre alto, brazos activos y zancada potente."},tempo_carrera:{b:"shown from the side running at a controlled strong tempo pace, upright efficient posture, steady rhythmic stride, arms driving smoothly, a sustained 'comfortably hard' effort",c:"Ritmo fuerte pero sostenible (umbral); mant\xE9n una cadencia constante y una respiraci\xF3n controlada y r\xEDtmica."},cuestas:{b:"shown from the side sprinting UP a short steep hill, marked forward lean into the slope, aggressive high knee drive, strong arm action, powerful push off the balls of the feet",c:"Sube corto y explosivo inclinando el cuerpo hacia la cuesta; empuja con fuerza y baja andando a recuperar."},caminar_suave:{b:"shown from the side walking at an easy pace, relaxed upright posture, natural arm swing, one foot rolling from heel to toe, calm and comfortable",c:"Paseo tranquilo y erguido; deja que los brazos se muevan con naturalidad y respira relajado."},caminar_rapido:{b:"shown from the side power-walking briskly, upright tall posture, purposeful bent-arm swing, quick heel-to-toe steps, engaged core, brisk determined pace",c:"Camina r\xE1pido con los brazos flexionados y activos; pasos cortos y \xE1giles, tronco erguido y abdomen firme."},caminar_cuesta:{b:"shown from the side walking UP an incline, slight forward lean into the slope, driving through the glutes and calves, arms swinging, steady climbing effort",c:"Sube la pendiente inclinando ligeramente el cuerpo y empujando con gl\xFAteo y gemelo; pasos firmes y constantes."},senderismo:{b:"shown from the side hiking on a trail with a light backpack, sturdy upright posture, one foot stepping onto uneven ground, arms balanced, an outdoor endurance walk",c:"Camina por terreno irregular con pasos seguros y mochila ligera; adapta el paso a la subida y bajada."},marcha_nordica:{b:"shown from the side Nordic walking with two poles, planting one pole and pushing back through it while the opposite leg strides forward, upright posture, engaging the arms and upper back",c:"Clava el bast\xF3n y emp\xFAjate hacia atr\xE1s con el brazo contrario a la pierna que avanza; trabaja tambi\xE9n el tren superior."},correr_suave:{b:"shown from the side jogging at an easy comfortable pace, relaxed mid-stride with a light float phase, moderate knee lift, loose hands, tall economical posture",c:"Trote suave y controlado; mant\xE9n los hombros relajados y una zancada econ\xF3mica bajo el cuerpo."},correr_largo:{b:"shown from the side running a long steady continuous run, economical relaxed stride, upright posture held over distance, smooth rhythmic arms, sustainable endurance effort",c:"Ritmo constante y sostenible durante mucho rato; cuida la postura y la respiraci\xF3n para aguantar la distancia."},sprint_recta:{b:"shown from the side at top-speed sprinting on a flat straight, maximal effort with an aggressive forward lean, very high knee drive, full float phase, arms driving hard, on the balls of the feet",c:"M\xE1xima velocidad en recta corta; empuja el suelo con fuerza, rodillas altas y brazos r\xE1pidos, y recupera del todo."},fartlek:{b:"shown from the side running at a strong varied pace, mid-stride with active arms and a clear sense of changing speed, focused expression, a playful speed-play effort",c:"Alterna tramos r\xE1pidos y suaves a tu gusto (juego de ritmos); cambia de velocidad seg\xFAn el terreno o el \xE1nimo."},subir_escaleras:{b:"shown from the side climbing a flight of stairs two-ish steps at a time, driving up through the front leg, torso slightly forward, arms assisting, powerful stepping cardio",c:"Sube empujando con el tal\xF3n de la pierna de arriba y el tronco algo adelantado; usa los brazos para el ritmo."},futbol_conduccion:{b:"shown from the side dribbling a football at pace, taking small quick touches with the inside of the foot while running between cones, athletic low posture, eyes up, ball close",c:"Toques cortos con el interior del pie manteniendo el bal\xF3n cerca; corre entre conos con la mirada al frente."},patinaje_linea:{b:"shown from the side inline skating, one leg pushing out to the side and back while gliding on the other, low athletic crouch, arms swinging, wearing a helmet, smooth lateral push",c:"Empuja lateralmente con una pierna y desliza sobre la otra en posici\xF3n baja; protege con casco y protecciones."},sf_caminata_de_pato:{b:"shown from the side walking forward in a deep squat 'duck walk', hips kept low below the knees throughout, torso upright, taking small steps while staying deep, quads and glutes under constant tension",c:"Camina manteni\xE9ndote agachado en sentadilla profunda con la cadera baja; pasos cortos sin subir el tronco."},sf_caminata_lateral_con_minibanda:{b:"shown from the front stepping sideways in a half-squat with a mini band around the ankles or knees, knees pushed out against the band, hips low and level, side-stepping against constant tension, glute medius working",c:"En media sentadilla con la banda en los tobillos, da pasos laterales manteniendo la tensi\xF3n y las rodillas abiertas."},nat_aquarunning:{b:"shown from the side suspended upright in deep water wearing a flotation belt, running in place with no ground contact, driving the knees and pumping the arms against the water, tall posture, a few stylized water lines",c:"Con cintur\xF3n de flotaci\xF3n, corre en vertical sin tocar el fondo; marca bien la rodilla y el braceo contra el agua."},cic_rodaje_z2:{b:"shown from the side cycling at a steady easy zone-2 pace, seated with hands on the hoods, smooth even pedal stroke, relaxed upper body, aerobic base effort",c:"Pedaleo aer\xF3bico c\xF3modo (zona 2): cadencia fluida, tronco relajado y esfuerzo en el que puedes conversar."},cic_cuestas_sentado:{b:"shown from the side cycling UP a climb while SEATED, hands on the bar tops, slightly forward torso, pushing a strong steady cadence up the gradient, quads and glutes loaded",c:"Sube sentado con una marcha algo dura y cadencia estable; mant\xE9n el peso atr\xE1s y el pedaleo redondo."},cic_cuestas_pie:{b:"shown from the side cycling UP a climb while STANDING out of the saddle, hips over the pedals, rocking the bike gently side to side, driving hard through each pedal, full-body climbing effort",c:"Sube de pie balanceando la bici con las manos; carga cada pedalada con el peso del cuerpo en tramos duros."},cic_sprints_15:{b:"shown from the side sprinting all-out on a bike, out of the saddle, torso low and forward, driving the pedals explosively at maximal power for a few seconds, intense effort",c:"Arranca a tope unos 15 s con una marcha dura, de pie y explosivo; recupera pedaleando suave entre repeticiones."},cic_recuperacion:{b:"shown from the side cycling very gently for recovery, seated upright and loose, light easy spinning with soft legs, calm relaxed posture",c:"Rodaje muy suave de recuperaci\xF3n; pedalea ligero y c\xF3modo, sin forzar, para soltar las piernas."},raq_escalera_pies:{b:"shown from the front doing fast footwork through a flat agility ladder on the floor, quick light steps in and out of the rungs, low athletic posture, arms active, blurring rapid feet",c:"Pies r\xE1pidos y ligeros dentro y fuera de la escalera; mantente bajo y en las puntas, mirada al frente."},bai_contemporaneo:{b:"shown full-body in an expressive contemporary-dance pose, fluid and grounded with a long extended reaching line, controlled balance, graceful continuous motion",c:"Movimiento fluido y expresivo que enlaza suelo y extensi\xF3n; controla el equilibrio y alarga cada l\xEDnea del cuerpo."},bici_estatica:{b:"shown from the side cycling on a stationary bike at a moderate pace, seated with hands on the bars, one leg driving the pedal down in a smooth round stroke, slight athletic forward lean",c:"Pedaleo moderado y constante; ajusta el sill\xEDn a la altura de la cadera y mant\xE9n un giro redondo y fluido."},bicicleta_exterior:{b:"shown from the side road cycling outdoors at a moderate pace, seated with hands on the hoods, wearing a helmet, smooth pedal stroke, relaxed aerodynamic posture",c:"Rueda a ritmo c\xF3modo con casco; mant\xE9n la espalda relajada, los codos algo flexionados y un pedaleo continuo."},bicicleta_sprints:{b:"shown from the side sprinting on a bike out of the saddle, low forward torso, driving the pedals explosively at high power, intense maximal effort",c:"Sprints cortos a m\xE1xima potencia con marcha dura; de pie y explosivo, con recuperaci\xF3n amplia entre ellos."},eliptica:{b:"shown from the side on an elliptical trainer, feet on the moving pedals and hands on the swinging handles, driving with a smooth low-impact striding motion, upright posture, arms and legs working together",c:"Movimiento fluido y sin impacto; empuja con las piernas y ayuda con los brazos manteniendo el tronco erguido."},cic_intervalos_4x4:{b:"shown from the side cycling hard during a 4-minute interval, seated and focused, strong steady high-power cadence, slight forward lean, sustained intense effort",c:"Cuatro bloques de 4 min fuertes (cerca del m\xE1ximo sostenible) con 3-4 min suaves entre ellos; mant\xE9n la potencia estable."},cic_intervalos_30_30:{b:"shown from the side cycling at a hard surge during a short 30-second interval, strong cadence, focused effort, alternating fast and easy",c:"Alterna 30 s fuertes y 30 s suaves; en los fuertes sube la cadencia y la potencia, y suelta en los flojos."},cic_sweet_spot:{b:"shown from the side cycling seated at a strong sustained sweet-spot pace, steady controlled high effort just below threshold, smooth cadence, focused posture",c:"Esfuerzo fuerte pero sostenible (justo por debajo del umbral) en bloques de 20 min; cadencia y potencia constantes."},cic_umbral_20:{b:"shown from the side cycling at a hard sustained threshold test pace, seated low and aero, gritted focused effort holding maximal steady power for the full effort",c:"Esfuerzo m\xE1ximo sostenido de 20 min para medir tu umbral; sal conservador y aprieta de forma constante."},cic_cadencia_alta:{b:"shown from the side cycling with very fast leg turnover at high cadence, seated smoothly with a light gear, hips stable and not bouncing, quick fluid pedal stroke",c:"Pedalea muy r\xE1pido (100+ rpm) con marcha ligera; busca que las caderas no reboten y el giro sea suave."},cic_fuerza_baja_cadencia:{b:"shown from the side cycling with a very heavy gear at low cadence, seated and pushing slow powerful pedal strokes, hips anchored, legs driving hard like a strength effort",c:"Marcha dura y cadencia baja (~50 rpm); empuja fuerte cada pedalada sentado, como un trabajo de fuerza."},cic_pedaleo_una_pierna:{b:"shown from the side cycling on a trainer with ONE leg clipped in and pedaling while the other rests off the pedal, focusing on a smooth full circular stroke, hips still, a technique drill",c:"Pedalea con una sola pierna en el rodillo para pulir el giro completo; busca eliminar los puntos muertos."},cic_salida_larga:{b:"shown from the side on a long endurance ride outdoors, seated comfortably with hands on the hoods, wearing a helmet, relaxed sustainable posture over distance",c:"Salida larga y sostenible; come y bebe con regularidad, alterna la posici\xF3n de manos y mant\xE9n un ritmo c\xF3modo."},cic_spinning:{b:"shown from the side on an indoor spinning bike in a class, standing out of the saddle driving the pedals to the rhythm, energetic upbeat posture, hands on the bars",c:"Sigue el ritmo alternando sentado y de pie; ajusta bien la resistencia para pedalear con control, no a lo loco."},cic_mtb_tecnica:{b:"shown from the side mountain biking over technical terrain, standing on the pedals in an attack position with bent elbows and knees, weight back, wearing a helmet, absorbing the trail",c:"En terreno t\xE9cnico, ponte de pie con codos y rodillas flexionados absorbiendo los baches; mira la trazada, no la rueda."},cic_eliptica_intervalos:{b:"shown from the side on an elliptical trainer pushing a hard interval, driving fast through the pedals and handles, upright focused posture, vigorous low-impact effort",c:"Alterna tramos intensos y suaves en la el\xEDptica; en los fuertes empuja con brazos y piernas a buen ritmo."},remoergometro_intervalos:{b:"shown from the side on an indoor rowing erg mid-drive during a hard interval, legs pressing the seat back, torso opening past vertical, arms about to pull the handle to the lower ribs, powerful sequenced effort",c:"Orden del tir\xF3n: primero piernas, luego tronco, luego brazos; en los intervalos aprieta el empuje de piernas."},remo_suave:{b:"shown from the side on an indoor rowing erg at a steady easy pace, smooth continuous stroke, legs-then-back-then-arms drive and a relaxed controlled recovery, calm posture",c:"Rema fluido y constante; recupera despacio (brazos-tronco-piernas) y no adelantes el tronco antes que las piernas."},ski_erg:{b:"shown from the front on a SkiErg, standing and reaching both handles up high overhead then driving them down past the hips with a crunch and a slight hip hinge, like double-poling in skiing, lats and core working",c:"Tira de ambas asas desde arriba hacia la cadera con un golpe de tronco; imita el bast\xF3n doble del esqu\xED de fondo."},remo_kayak:{b:"shown from the front paddling a kayak, seated with a two-bladed paddle, rotating the torso to plant one blade forward and pull it back alongside while the other rises, core-driven rotation, wearing a life vest",c:"El impulso sale del giro del tronco, no solo de los brazos; alterna palada a cada lado con la espalda recta."},surf_remada:{b:"shown from the side lying prone on a surfboard paddling, chest and head lifted, arms alternately reaching forward and pulling water like front-crawl, back arched, a few stylized water lines",c:"Tumbado en la tabla con el pecho alto, brazea alternando como en crol; mant\xE9n la mirada al horizonte."},surf_popup:{b:"shown from the side in the explosive surf pop-up, pushing up from lying prone on the board straight into a low crouched surfing stance, one foot forward, knees bent, arms out for balance",c:"Del tumbado a la posici\xF3n de surf de un impulso: manos bajo el pecho, empuja y planta los pies en una zancada baja."},rem_500:{b:"shown from the side on a rowing erg driving a hard 500 m sprint, strong explosive leg drive, torso swinging back, handle pulled to the sternum, maximal focused effort",c:"Sprint corto: sal fuerte pero controla el ritmo para no fundirte; potencia de piernas en cada palada."},rem_2000:{b:"shown from the side on a rowing erg pacing a 2000 m test, powerful steady stroke, sequenced legs-back-arms drive, focused sustained effort",c:"La distancia de referencia: reparte el esfuerzo, mant\xE9n una palada potente y controla la respiraci\xF3n."},rem_intervalos_250:{b:"shown from the side on a rowing erg during a short 250 m sprint interval, explosive full-power stroke, legs driving hard, handle to the ribs, intense effort",c:"Repeticiones cortas a tope de 250 m con descanso amplio; busca m\xE1xima potencia en cada palada."},rem_continuo_5k:{b:"shown from the side on a rowing erg at a long steady 5000 m pace, smooth economical continuous stroke, relaxed sustainable posture, endurance effort",c:"Rema largo y constante a un ritmo sostenible; cuida la t\xE9cnica cuando llegue el cansancio."},rem_tecnica_pasada:{b:"shown from the side on a rowing erg doing a technique drill by segments, pausing to isolate the arms-only, then arms-and-body, then the full stroke, controlled and deliberate posture",c:"Descomp\xF3n la palada por partes (solo brazos, brazos+tronco, completa) para pulir la t\xE9cnica y el orden del tir\xF3n."},rem_skierg_intervalos:{b:"shown from the front on a SkiErg during a hard interval, driving both handles powerfully from overhead down past the hips with a strong core crunch, vigorous double-pole effort",c:"Intervalos de doble bast\xF3n: tira fuerte desde arriba con el tronco; alterna esfuerzo y recuperaci\xF3n."},rem_kayak_plano:{b:"shown from the front paddling a kayak on flat calm water at a steady pace, seated with a two-bladed paddle, smooth torso-rotation strokes side to side, relaxed cruising effort, life vest on",c:"En aguas tranquilas, palada larga y relajada girando el tronco; mant\xE9n un ritmo c\xF3modo y constante."},rem_kayak_intervalos:{b:"shown from the front paddling a kayak hard during an interval, strong fast torso-driven strokes catching a lot of water each side, intense focused effort",c:"Tramos r\xE1pidos de palada potente girando el tronco, con recuperaci\xF3n entre ellos; agarra bien el agua."},rem_paddle_surf:{b:"shown from the side standing on a paddle-board (SUP), knees soft, planting a single long paddle forward and pulling it back alongside the board, torso rotating, core balancing, calm water lines",c:"De pie sobre la tabla con rodillas blandas; clava la pala vertical y tira girando el tronco, no solo el brazo."},nadar_crol:{b:"shown from the side swimming front-crawl at the surface, streamlined body, one arm reaching forward into the catch while the other finishes the pull at the hip, face down with a side breath, flutter kick, clean water lines",c:"Alarga la brazada al entrar y rueda el cuerpo para respirar de lado; patada continua desde la cadera."},nadar_braza:{b:"shown from the front swimming breaststroke, arms sweeping out and together in a heart-shaped pull while the legs finish a whip kick, gliding forward in a streamline, head rising to breathe then dropping",c:"Coordina tir\xF3n de brazos y patada de rana con un deslizamiento entre ciclos; respira al cerrar los brazos."},nadar_espalda:{b:"shown from the side swimming backstroke, lying face-up at the surface, one straight arm entering overhead while the other exits at the hip, body rolling side to side, steady flutter kick",c:"Boca arriba, entra con el me\xF1ique y rueda el cuerpo; mant\xE9n la cadera alta y una patada continua."},nadar_mariposa:{b:"shown from the side swimming butterfly, both arms recovering forward together over the water while the hips drive a dolphin undulation, chest pressing down, an explosive symmetrical stroke",c:"Ondula desde el pecho y la cadera; los dos brazos entran juntos y la patada de delf\xEDn marca el ritmo."},patada_crol_tabla:{b:"shown from the side kicking front-crawl legs while holding a kickboard out front with straight arms, face down, a steady flutter kick driven from the hips, streamlined body at the surface",c:"Con la tabla al frente, patea desde la cadera con las piernas casi rectas y los tobillos sueltos; cadera alta."},aquagym:{b:"shown from the front standing in chest-deep water doing an aqua-aerobics move, driving the arms and knees against the water resistance, upright energetic posture, water splashing lightly",c:"Aprovecha la resistencia del agua moviendo brazos y piernas con amplitud; mant\xE9n el tronco firme y el ritmo alegre."},nat_crol_series_50:{b:"shown from the side swimming fast front-crawl in a 50 m repeat, strong high-tempo stroke, powerful catch and pull, tight streamline, focused sprint effort",c:"Series cortas y r\xE1pidas de 50 m con descanso; nada fuerte pero sin perder la t\xE9cnica de la brazada."},nat_crol_series_100:{b:"shown from the side swimming strong front-crawl in a 100 m repeat, well-paced powerful stroke, good body roll and catch, controlled fast effort",c:"Series de 100 m a ritmo fuerte y sostenible; controla la respiraci\xF3n y mant\xE9n la brazada larga."},nat_crol_series_200:{b:"shown from the side swimming steady front-crawl in a 200 m repeat, efficient rhythmic stroke, relaxed powerful catch, aerobic sustained effort",c:"Series de 200 m a ritmo aer\xF3bico constante; busca eficiencia y una brazada regular de principio a fin."},nat_crol_400:{b:"shown from the side swimming continuous front-crawl over 400 m, smooth economical stroke held over distance, steady bilateral breathing, endurance effort",c:"400 m continuos a ritmo c\xF3modo; nada largo y relajado cuidando la t\xE9cnica cuando aparezca el cansancio."},nat_crol_1000:{b:"shown from the side swimming long continuous front-crawl over 1000 m, very economical relaxed stroke, calm rhythmic breathing, sustained endurance posture",c:"Distancia larga y constante; c\xE9ntrate en una brazada eficiente y una respiraci\xF3n r\xEDtmica que puedas mantener."},nat_estilos_im:{b:"shown from the side swimming an individual-medley transition, mid-stroke with a sense of changing style (butterfly, backstroke, breaststroke, front-crawl), athletic surface posture, dynamic water lines",c:"Encadena los cuatro estilos (mariposa, espalda, braza, crol); cuida los virajes y la transici\xF3n entre ellos."},nat_pies_tabla_crol:{b:"shown from the side kicking front-crawl legs holding a kickboard ahead, face down, a compact fast flutter kick from the hips, hips high and body streamlined at the surface",c:"Con tabla, patada de crol r\xE1pida y compacta desde la cadera; punta de pie estirada y tobillo relajado."},nat_pies_espalda:{b:"shown from the side kicking backstroke legs face-up at the surface, arms streamlined overhead or by the sides, steady flutter kick from the hips, hips kept high, toes just breaking the surface",c:"Boca arriba, patada continua desde la cadera con la punta apenas rompiendo el agua; mant\xE9n la cadera alta."},nat_pies_lateral:{b:"shown from the side kicking in a side-lying position, one arm extended forward, body rolled onto its side, flutter-kicking while balanced on the side, a body-position technique drill",c:"Nada de lado con un brazo extendido y patea; ejercicio para sentir el rolido y el equilibrio del cuerpo."},nat_brazos_pullbuoy:{b:"shown from the side swimming front-crawl arms-only with a pull-buoy squeezed between the thighs, legs still and floating, focusing on a strong catch and pull, upper body driving, streamlined",c:"Con el pull-buoy entre los muslos y sin patear, c\xE9ntrate en un agarre firme del agua y una brazada larga."},nat_palas:{b:"shown from the side swimming front-crawl wearing hand paddles, exaggerated strong catch and pull with the enlarged surface, pull-buoy optional, powerful upper-body stroke, clean water lines",c:"Con palas, siente el agarre del agua y tira con fuerza controlada; empieza con series cortas para cuidar el hombro."},nat_aletas:{b:"shown from the side swimming front-crawl wearing fins, a strong propulsive flutter kick from the hips, streamlined fast body position, arms in a relaxed long stroke, dynamic water lines",c:"Con aletas, patea desde la cadera con piernas largas; aprovecha la velocidad para pulir la posici\xF3n del cuerpo."},nat_hipoxia:{b:"shown from the side swimming front-crawl with reduced breathing (hypoxic drill), face down holding the breath over several strokes, controlled tight streamline, focused effort",c:"Respira cada m\xE1s brazadas de lo normal (p. ej. cada 5-7) para trabajar el control; no fuerces si te falta el aire."},nat_tecnica_puno:{b:"shown from the side swimming front-crawl with CLOSED FISTS instead of open hands, forcing the forearms to feel and press the water, streamlined body, a catch-awareness technique drill",c:"Nada con los pu\xF1os cerrados para aprender a agarrar el agua con el antebrazo; luego abre la mano y nota la diferencia."},nat_tecnica_6_1_6:{b:"shown from the side doing the 6-1-6 front-crawl drill, gliding on one side kicking six times, taking one single stroke to roll to the other side, then six kicks again, emphasising body roll and balance",c:"Seis patadas de lado, una brazada para cambiar de lado, seis patadas: pule el rolido y el equilibrio del cuerpo."},nat_viraje:{b:"shown from the side performing a front-crawl flip turn at the wall, tucking into a fast forward somersault and planting both feet on the wall, then pushing off in a tight streamline underwater",c:"Llega fuerte a la pared, voltea r\xE1pido y empuja en posici\xF3n hidrodin\xE1mica bien estirada bajo el agua."},nat_salida_bloque:{b:"shown from the side in a racing start on a starting block, crouched and gripping the front edge, weight forward ready to spring out into a long flat dive over the water",c:"Ag\xE1rrate al poyete con el peso adelantado y salta largo y estirado; entra al agua con las manos primero."},nat_braza_series:{b:"shown from the front swimming breaststroke in a 100 m repeat, coordinated heart-shaped arm pull and whip kick with a glide between strokes, head rising to breathe, steady strong effort",c:"Series de 100 m de braza; sincroniza tir\xF3n y patada con un deslizamiento y mant\xE9n un ritmo constante."},nat_espalda_series:{b:"shown from the side swimming backstroke in a 100 m repeat, face-up with alternating straight-arm strokes and steady flutter kick, body rolling, high hips, sustained effort",c:"Series de 100 m de espalda; rueda el cuerpo, entra con el brazo recto y mant\xE9n la cadera alta."},nat_mariposa_series:{b:"shown from the side swimming butterfly in short 25 m repeats, both arms recovering over the water together with a dolphin kick from the hips, chest pressing, explosive symmetrical effort",c:"Series cortas de 25 m de mariposa; c\xE9ntrate en el ritmo de la ondulaci\xF3n y no en la fuerza bruta de brazos."},nat_aguas_abiertas:{b:"shown from the side swimming front-crawl in open water wearing a wetsuit, lifting the head forward to sight a buoy every few strokes, strong steady stroke, a bright tow-float trailing, textured water",c:"En aguas abiertas, levanta la vista cada varias brazadas para orientarte (sighting); nada con neopreno y boya."},nat_recuperacion:{b:"shown from the side swimming very gently for recovery, an easy relaxed loose stroke, calm breathing, unhurried streamlined body at the surface",c:"Nado muy suave y relajado para soltar; alterna estilos si quieres y respira tranquilo, sin buscar ritmo."},box_jump:{b:"shown from the side at the apex of a box jump, exploding up from a quarter-squat with both feet and swinging the arms up to land softly on top of a sturdy box, hips and knees extending powerfully",c:"Baja a un cuarto de sentadilla, salta impulsando los brazos y aterriza suave y flexionado sobre el caj\xF3n."},burpees:{b:"shown from the side mid-burpee at the explosive jump-up phase, arms overhead just after springing from the floor, having gone from a chest-to-floor position to a full-body jump, dynamic athletic motion",c:"Baja a plancha con el pecho al suelo, recoge los pies de un salto y salta arriba con los brazos; enlaza fluido."},jumping_jacks:{b:"shown from the front mid jumping-jack, legs jumped wide apart while both arms swing up overhead in a star shape, upright bouncy posture, on the balls of the feet",c:"Abre piernas y sube los brazos a la vez formando una estrella, y cierra al saltar; ritmo continuo y ligero."},mountain_climbers:{b:"shown from the side in a high plank driving one knee toward the chest while the other leg stays extended, hips low and level, alternating the knees quickly, shoulders over the hands, core braced",c:"En plancha alta, lleva las rodillas al pecho alternando r\xE1pido sin subir la cadera; hombros sobre las manos."},battle_ropes:{b:"shown from the front in an athletic half-squat gripping one heavy battle rope in each hand, whipping both arms up and down to send powerful alternating waves down the ropes, braced core",c:"En media sentadilla, genera ondas r\xE1pidas y potentes moviendo los brazos con fuerza; mant\xE9n el core firme."},futbol_cambios_direccion:{b:"shown from the side making a sharp cutting change of direction around cones, planting the outside foot hard and pushing off explosively the other way, low athletic posture, arms out for balance",c:"Frena con el pie de fuera y reacelera al lado contrario en posici\xF3n baja; da pasos cortos para cambiar r\xE1pido."},baloncesto_desplazamiento_defensivo:{b:"shown from the front in a basketball defensive slide, low wide athletic stance with a flat back, sliding sideways without crossing the feet, arms spread, staying down and balanced",c:"Posici\xF3n baja y ancha; desl\xEDzate de lado sin cruzar los pies y con los brazos abiertos, mirada al frente."},baloncesto_tiro_suspension:{b:"shown from the side rising into a basketball jump shot, leaping straight up with the shooting arm extending overhead and the wrist flicking the follow-through, balanced in the air, focused",c:"Salta recto, suelta el bal\xF3n en el punto alto y termina con la mu\xF1eca relajada; equilibrio y misma mec\xE1nica siempre."},bear_crawl:{b:"shown from the side in a bear crawl, on hands and feet with the knees hovering just off the floor, moving the opposite hand and foot forward together, flat back, hips low and level, core braced",c:"A cuatro apoyos con las rodillas a un palmo del suelo; avanza mano y pie contrarios manteniendo la cadera baja."},salto_comba:{b:"shown from the front skipping rope, bouncing lightly on the balls of both feet as the rope passes underfoot, wrists doing the turning close to the hips, tall relaxed posture",c:"Salta bajito sobre las puntas y gira la cuerda con las mu\xF1ecas, no con los brazos; mant\xE9n el tronco erguido."},voleibol_saltos_bloqueo:{b:"shown from the front at the top of a volleyball block jump at the net, both arms reaching straight up with spread hands and stiff wrists, body extended vertically, penetrating over an imagined net",c:"Salta vertical junto a la red con los brazos rectos y las manos firmes; sube por encima sin tocar la red."},voleibol_remate:{b:"shown from the side in a volleyball spike approach and hit, leaping off a two-foot plant with the hitting arm cocked high and swinging down to strike the ball at full reach, explosive whole-body motion",c:"Aprox\xEDmate, salta con los dos pies y golpea arriba con el brazo estirado; usa el impulso de la carrera."},esqui_alpino_simulado:{b:"shown from the front doing simulated alpine-ski hops, feet together jumping side to side over an imaginary line, knees bent and absorbing each landing, hips loaded, arms forward for balance",c:"Salta lateral con los pies juntos amortiguando con las rodillas; imita el vaiv\xE9n del esqu\xED manteni\xE9ndote bajo."},hockey_patron_lateral:{b:"shown from the side in a low hockey skating stance shuffling laterally, deep knee bend and forward torso lean, pushing off the outside leg side to side, holding a stick out front",c:"Muy agachado y con el tronco adelantado, empuja de lado con la pierna de fuera; pasos amplios y potentes."},rugby_empuje_trineo:{b:"shown from the side driving a rugby push-sled, body in a strong forward diagonal with a flat braced back, shoulders into the pads and legs churning to push the sled forward, powerful leg drive",c:"Cuerpo inclinado y espalda firme contra el trineo; empuja con pasos cortos y potentes clavando los pies."},sf_sentadilla_con_salto:{b:"shown from the side at the explosive take-off of a jump squat, having dropped to a squat and now springing straight up with the hips and knees extending and the arms swinging up, landing soft",c:"Baja a sentadilla y salta explosivo hacia arriba; aterriza flexionando rodillas y cadera para amortiguar."},sf_salto_rodillas_al_pecho:{b:"shown from the side at the apex of a tuck jump, having sprung straight up and pulling both knees up toward the chest at the top, arms swinging, landing softly with bent knees",c:"Salta recto hacia arriba y sube las rodillas al pecho en el aire; aterriza suave y flexionado, sin bloquear."},kettlebell_swing:{b:"shown from the side at the top of a kettlebell swing, a kettlebell floated up to about chest height by an explosive hip snap, arms straight and relaxed, hips and knees just extended, flat neutral back \u2014 a hip hinge, not a squat",c:"El impulso sale de un golpe de cadera, no de los brazos; hombros atr\xE1s y proyecta la pesa hasta el pecho."},baile_cardio:{b:"shown full-body in an upbeat cardio-dance move, energetic and rhythmic with the arms and hips swinging to the beat, light on the feet, joyful expressive posture",c:"Sigue el ritmo con brazos y cadera; mantente ligero sobre los pies y disfruta el movimiento continuo."},zumba:{b:"shown full-body in a lively Zumba step, hips swinging in a Latin-dance move with the arms raised and expressive, bouncing on the balls of the feet, festive energetic posture",c:"Deja que la cadera lidere los pasos latinos y acompa\xF1a con los brazos; lo importante es moverse sin parar."},golf_swing:{b:"shown from behind at the top of a golf swing, the club swung back over the shoulder with a full torso coil, hips loaded and wrists hinged, poised to unwind through the ball, balanced athletic posture",c:"Gira el tronco cargando la cadera en la subida y desenrosca de abajo arriba; termina en equilibrio sobre el pie adelantado."},bai_salsa:{b:"shown full-body in a salsa/bachata step, a partner-dance basic with a compact quick-quick-slow footwork, soft knee bounce and hip motion, one arm framed, elegant lively posture",c:"Marca el paso b\xE1sico con las rodillas blandas y deja que la cadera surja del peso; mant\xE9n el tronco erguido."},bai_hiphop:{b:"shown full-body in a grounded hip-hop groove, knees bent in a low bounce with sharp isolated arm and chest movements, urban confident attitude, athletic posture",c:"Baila con las rodillas flexionadas y un rebote grave; marca los acentos con brazos y pecho, con actitud."},bai_ballet_fit:{b:"shown from the side at a ballet-barre fitness position, one hand resting on a barre or chair, standing tall with turned-out legs doing a controlled pli\xE9 or leg lift, elegant elongated line, core engaged",c:"Postura alta y estirada con apoyo ligero en la barra; movimientos peque\xF1os y controlados apretando el core y el gl\xFAteo."},bai_batuka:{b:"shown full-body in an energetic aerobic-dance move (Batuka style), big rhythmic arm swings and marching steps to the beat, upbeat vigorous posture, light on the feet",c:"Movimientos amplios de brazos y piernas al ritmo; prioriza mantener la intensidad y el buen humor."},bai_coreo_hiit:{b:"shown full-body mid dance-HIIT choreography, an athletic high-energy move blending a dance step with a burst of exercise, dynamic and explosive, focused expressive posture",c:"Encadena los pasos coreografiados a alta intensidad; cuando suba el pulso, cuida la t\xE9cnica y respira."},bai_flamenco:{b:"shown from the side in a flamenco stance, upright proud posture with a tall arched back, arms raised in a curved frame while the feet drive a rhythmic heel-and-toe stamp, intense expressive line",c:"Tronco muy erguido y brazos en marco; marca el zapateado con el peso justo, alternando tal\xF3n y planta."},bai_swing:{b:"shown full-body in a bouncy swing/lindy-hop step, a springy partner-dance basic with a light knee bounce and playful kicks, one arm framed, cheerful energetic posture",c:"Marca el rebote alegre sobre las puntas con las rodillas sueltas; el swing vive en el pulso relajado y constante."},boxeo_sombra:{b:"shown from the side shadow-boxing, in a boxing stance on the balls of the feet, throwing a straight punch with the rear hand extending while the lead hand guards the chin, hips rotating, light and mobile",c:"Manos arriba y barbilla protegida; lanza los golpes girando la cadera y vuelve r\xE1pido a la guardia, sin parar de moverte."},boxeo_saco:{b:"shown from the side hitting a hanging heavy bag, in a boxing stance driving a powerful cross into the bag, rotating the hips and pivoting the rear foot, the other hand guarding, wearing gloves and wraps",c:"Pega girando la cadera y el pie de atr\xE1s, no solo con el brazo; recupera la guardia al instante tras cada golpe."},kickboxing_patadas:{b:"shown from the side landing a kickboxing kick into a heavy bag, the rear leg swinging up to strike with the shin while the support foot pivots and the arms guard the head, balanced follow-through",c:"Gira el pie de apoyo al patear e impacta con la espinilla; mant\xE9n la guardia arriba y recobra el equilibrio."},artes_marciales_kata:{b:"shown full-body in a martial-arts kata stance, a crisp controlled form pose with a low grounded stance, one arm blocking and the other chambered, focused disciplined posture",c:"Ejecuta la forma con posiciones firmes y transiciones controladas; precisi\xF3n y respiraci\xF3n marcan el ritmo."},sf_patadas_traseras:{b:"shown from the side performing a triceps kickback, torso hinged forward to near-parallel with a flat back, the upper arm pinned to the side and parallel to the floor, extending the forearm straight back to full elbow lockout, triceps squeezed",c:"Inclina el tronco y fija el brazo pegado al costado; extiende solo el antebrazo hacia atr\xE1s y aprieta el tr\xEDceps."},sf_patadas_de_burro:{b:"shown from the side on all fours performing donkey kicks, hands under shoulders and knees under hips, driving one bent knee up and back so the sole faces the ceiling, hips level, glute squeezed at the top",c:"A cuatro apoyos, sube un tal\xF3n hacia el techo con la rodilla doblada apretando el gl\xFAteo, sin arquear la lumbar."},com_sombra_rounds:{b:"shown from the side shadow-boxing through a round, moving on the balls of the feet in a stance, throwing a combination of punches into the air with the hips rotating, mobile and rhythmic, hands up",c:"Trabaja por asaltos encadenando combinaciones y desplazamientos; mant\xE9n el ritmo y no bajes las manos al cansarte."},com_manoplas:{b:"shown from the side hitting focus mitts held by a partner, driving a punch into the pad with the hips rotating and the rear foot pivoting, the other hand guarding, gloves and wraps on",c:"Golpea el centro de la manopla con la cadera; escucha las combinaciones del compa\xF1ero y vuelve siempre a la guardia."},com_saco_series:{b:"shown from the side landing a hard power punch into a heavy bag during a power series, full hip rotation and rear-foot pivot behind the punch, braced core, gloves on, forceful follow-through",c:"Series cortas de m\xE1xima potencia; carga cada golpe desde el suelo y la cadera y descansa entre tandas."},com_comba_boxeo:{b:"shown from the front skipping a boxing rope, bouncing lightly on the balls of the feet with a quick relaxed rhythm, wrists turning the rope near the hips, tall loose posture",c:"Salto de comba ligero y continuo sobre las puntas; gira con las mu\xF1ecas y busca un ritmo relajado que aguantes."},com_esquivas:{b:"shown from the side in a boxing slip, bending the knees and shifting the torso to one side to duck under an imagined punch, hands up guarding, weight loaded on one leg, ready to counter",c:"Esquiva flexionando las piernas y moviendo la cintura, no la cabeza sola; vuelve al centro con las manos arriba."},com_rodillas_clinch:{b:"shown from the side throwing a knee strike from the clinch, both hands gripping behind an opponent's neck (or a bag), driving one knee explosively up into the target, hips thrusting, on the ball of the support foot",c:"Agarra la nuca y tira hacia abajo mientras subes la rodilla con un empuje de cadera; alterna piernas."},com_patada_circular:{b:"shown from the side landing a roundhouse kick, the rear leg swinging horizontally to strike with the shin while the support foot pivots fully and the hips rotate over, arms guarding, powerful arc",c:"Gira el pie de apoyo del todo y haz pasar la cadera por encima; impacta con la espinilla, no con el empeine."},com_patada_frontal:{b:"shown from the side landing a front push kick (teep), the knee lifting then the leg extending straight forward to push with the ball of the foot into the target, hips pushing through, hands up, balanced",c:"Sube la rodilla y empuja al frente con la planta del pie como un pist\xF3n; usa la cadera y no pierdas la guardia."},com_guardia_desplaz:{b:"shown from the side in a boxing guard footwork drill, hands up in a tight stance, stepping and pivoting to move around while keeping the feet under the hips, balanced and mobile, never crossing the feet",c:"Mu\xE9vete con pasos cortos sin cruzar los pies y sin perder la guardia; mant\xE9n siempre el equilibrio para golpear."},com_sparring_tecnico:{b:"shown from the side in controlled technical sparring, two guards facing off with light measured punches and defensive movement, headgear and gloves on, focused and controlled, not full power",c:"Esp\xE1rring suave y controlado: prioriza t\xE9cnica, distancia y defensa sobre la potencia; protege bien la cabeza."},com_defensa_bloqueos:{b:"shown from the side in a boxing defensive block, forearms and gloves raised tight to cover the head and body against an incoming strike, elbows in, chin tucked, braced stance",c:"Cubre con antebrazos y guantes pegados a la cabeza y el ment\xF3n metido; bloquea sin bajar los codos."},tenis_golpes_fondo:{b:"shown from the side hitting a tennis groundstroke from the baseline, rotated hips and shoulders with the racket swinging low-to-high to meet the ball out in front, athletic split stance, follow-through over the shoulder",c:"Prepara pronto girando el tronco y golpea delante del cuerpo de abajo arriba; termina el gesto sobre el hombro."},tenis_saques:{b:"shown from the side in the tennis serve trophy position, tossing arm up and the racket dropping behind the back, knees bent ready to drive up and explode into the ball overhead, full extension",c:"Lanza la bola arriba y adelante, carga las piernas y golpea en m\xE1xima extensi\xF3n; deja caer la raqueta tras la espalda antes de subir."},padel_pared_y_volea:{b:"shown from the side playing a padel volley near the net, compact block of the ball with a short punch of the racket, knees bent in a ready stance, other hand out for balance, controlled contact",c:"Volea corta y firme bloqueando la bola delante; flexiona las piernas y controla, no impulses con todo el brazo."},badminton_desplazamientos:{b:"shown from the side moving explosively around a badminton court, lunging toward a low shuttle with the racket extended, quick recovery footwork, low athletic ready posture, light and fast",c:"Sal explosivo del centro y vuelve tras cada golpe; da el \xFAltimo paso largo hacia el volante y recupera la posici\xF3n."},raq_derecha_cruzada:{b:"shown from the side hitting a cross-court forehand, rotating the hips and shoulders to send the ball diagonally, meeting it out in front with a low-to-high swing, athletic stance, long follow-through",c:"Golpe de derecha cruzado en diagonal; abre un poco el gesto y contacta delante girando el tronco."},raq_reves:{b:"shown from the side hitting a backhand, torso rotated with the racket coming across the body to meet the ball out front (one or two hands), balanced stance, controlled follow-through",c:"Rev\xE9s con giro de hombros; contacta delante y acompa\xF1a la bola, ya sea a una o dos manos, sin frenar el gesto."},raq_voleas:{b:"shown from the side hitting a volley at the net, a compact punch of the racket meeting the ball in front with almost no backswing, knees bent, firm wrist, other arm out for balance",c:"Volea corta y firme sin apenas armar; bloquea la bola delante con la mu\xF1eca fija y las piernas flexionadas."},raq_smash:{b:"shown from the side hitting an overhead smash, the racket swung up and over to strike a high ball downward at full reach, body extending upward, hips and shoulder driving the powerful downward hit",c:"Col\xF3cate bajo la bola y golpea arriba y adelante en m\xE1xima extensi\xF3n; usa el tronco para pegar hacia abajo."},raq_saque_plano:{b:"shown from the side serving a flat tennis serve, full extension upward driving straight through the ball for pace, toss in front, legs pushing up, aggressive follow-through across the body",c:"Saque plano y r\xE1pido: lanza la bola adelante y golpea en extensi\xF3n buscando velocidad; acompa\xF1a hacia el otro lado."},raq_saque_liftado:{b:"shown from the side serving a kick/slice serve, brushing up and across the back of the ball with the racket for spin, arched back and legs driving up, spin-oriented follow-through",c:"Saque con efecto: cepilla la bola de abajo arriba (liftado) o de lado (cortado); arquea y sube desde las piernas."},raq_dejada:{b:"shown from the side playing a delicate drop shot, a soft open-faced touch of the racket under the ball to float it just over the net, knees bent, gentle controlled contact, no power",c:"Toque suave con la cara abierta para dejar la bola muerta cerca de la red; controla con el tacto, no con fuerza."},raq_multibola:{b:"shown from the side in a fast multi-ball drill, hitting a groundstroke and immediately resetting for the next feed, high-tempo repeated swings, athletic ready posture, continuous rhythm",c:"Golpe tras golpe sin descanso: prioriza la t\xE9cnica y la recuperaci\xF3n r\xE1pida al centro entre cada bola."},raq_pared:{b:"shown from the side rallying against a wall, hitting a controlled groundstroke into the wall and resetting for the rebound, steady rhythmic swings, athletic ready stance",c:"Pelotea contra la pared buscando regularidad; ajusta la fuerza para mantener un intercambio largo y constante."},raq_padel_bandeja:{b:"shown from the side hitting a padel 'bandeja' overhead, a controlled slice smash taken high to the side with a compact swing, keeping the point rather than winning it, balanced stance, spin contact",c:"La bandeja es un remate controlado, no matador: golpea arriba y al lado con corte para mantener la posici\xF3n en la red."},raq_padel_vibora:{b:"shown from the side hitting a padel 'v\xEDbora' overhead, an aggressive slicing smash struck with a whippy wrist and side spin, more attacking than a bandeja, athletic coiled posture",c:"La v\xEDbora es una bandeja m\xE1s agresiva con mu\xF1eca y efecto lateral; golpea arriba buscando velocidad y bote bajo."},raq_padel_salida_pared:{b:"shown from the side playing a ball off the back glass in padel, waiting for the rebound and hitting it out from the wall with a smooth low-to-high swing, patient balanced stance",c:"Espera a que la bola salga de la pared y acomp\xE1\xF1ala de abajo arriba; ten paciencia y no te eches encima del cristal."},movilidad_tobillo:{b:"shown from the side in a half-kneeling ankle mobility drill, one foot flat in front with the knee driving forward past the toes over a stable foot, heel staying down, gently stretching the ankle, calm controlled posture",c:"Con el pie plano, lleva la rodilla hacia delante por encima de los dedos sin despegar el tal\xF3n; movimiento lento."},estiramiento_flexor_cadera:{b:"shown from the side in a half-kneeling hip-flexor stretch, one knee down and the other foot forward, gently pushing the hips forward and tucking the pelvis to lengthen the front of the rear hip, tall torso",c:"Rodilla en el suelo y cadera hacia delante metiendo el pubis; siente el estiramiento en la ingle de la pierna de atr\xE1s."},cat_cow:{b:"shown from the side on all fours doing cat-cow, alternately rounding the spine up toward the ceiling (cat) and dropping the belly with the chest and tailbone lifting (cow), a slow flowing spinal mobilization",c:"A cuatro apoyos, alterna redondear la espalda (gato) y arquearla abriendo el pecho (vaca) al ritmo de la respiraci\xF3n."},yoga_saludo_sol:{b:"shown from the side in a sun-salutation flow position, mid-transition through a graceful yoga sequence such as an upward reach or forward fold, controlled breath and long extended lines, calm balance",c:"Encadena las posturas con la respiraci\xF3n: inhala al abrir y estirar, exhala al plegar; movimiento fluido y consciente."},yoga_guerrero:{b:"shown from the front in the yoga warrior pose, a wide stance with the front knee bent over the ankle and the rear leg straight, arms extended strongly out or overhead, gaze forward, steady grounded posture",c:"Rodilla delantera sobre el tobillo y pierna trasera firme; estira los brazos y abre el pecho respirando con calma."},pilates_cien:{b:"shown from the side doing the Pilates hundred, lying supine with the head and shoulders curled up, legs extended low, arms straight by the sides pulsing up and down, deep steady breathing, abs braced",c:"Cabeza y hombros elevados con las piernas estiradas; bombea los brazos arriba y abajo respirando de forma marcada."},pilates_roll_up:{b:"shown from the side doing the Pilates roll-up, lying supine with arms overhead then peeling the spine off the floor one vertebra at a time to reach toward the toes, then rolling back down with control",c:"Sube y baja v\xE9rtebra a v\xE9rtebra de forma controlada, sin impulso; alarga hacia los pies con el abdomen."},animal_flow_beast:{b:"shown from the side in an animal-flow beast hold, on hands and toes with the knees hovering a few centimetres off the floor, flat back and braced core, a strong stable quadruped hold",c:"Manos y pies apoyados con las rodillas a un palmo del suelo; mant\xE9n la espalda plana y el abdomen muy firme."},sf_abdominales_con_brazos_estirados:{b:"shown from the side doing a crunch with the arms extended straight overhead, lying supine with knees bent, curling the shoulder blades up while the long arms reach past the head, upper abs working against the longer lever",c:"Brazos estirados detr\xE1s de la cabeza (palanca m\xE1s larga); enrolla los hombros hacia arriba sin tirar del cuello."},nat_respiracion_bilat:{b:"shown from the side swimming front-crawl practising bilateral breathing, rolling the head to breathe alternately to both sides every few strokes, streamlined body, calm rhythmic technique drill",c:"Respira alternando a los dos lados (cada 3 brazadas); rueda el cuerpo para respirar sin levantar la cabeza."},beisbol_lanzamiento:{b:"shown from the side in a baseball throwing motion, striding forward with the arm cocked back and the shoulders coiled, about to whip the ball forward with a powerful trunk rotation and arm follow-through across the body",c:"El lanzamiento sale del suelo y la cadera: da el paso, gira el tronco y acompa\xF1a el brazo cruzando el cuerpo."}};(function(){if(!(typeof EXERCISES>"u"))for(var a in EX_DESC)EX_DESC.hasOwnProperty(a)&&EXERCISES[a]&&EX_DESC[a]&&EX_DESC[a].c&&(EXERCISES[a].cues=EX_DESC[a].c)})(),typeof window<"u"&&(window.EX_DESC=EX_DESC);


